/* =============================================================================================
   ProCargo database - full install / upgrade (schema, procedures, seed data, security)
   GENERATED by build-ssms-scripts.sh from the numbered folders. Do not edit by hand.

   How to run: open in SSMS, connect to your SQL Server (any database), press F5 (Execute).
   Safe to run again: every statement is IF NOT EXISTS / CREATE OR ALTER / MERGE, so it upgrades
   an existing ProCargo database without deleting data. Check the Messages tab ends with
   'ProCargo install completed' and shows no red errors.
   Then run ProCargo_TestData.sql for the development accounts (local testing only).
   ============================================================================================= */
SET NOCOUNT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

USE [master];
GO

-- >>>>> 01-Database/001_CreateDatabase.sql
/*
    ProCargo Logistics - Database creation
    Run against the [master] database. All later scripts run against [ProCargo].
    Collation: case-insensitive, accent-sensitive Latin collation (default for Indian English locales).
*/
IF DB_ID(N'ProCargo') IS NULL
BEGIN
    CREATE DATABASE [ProCargo] COLLATE SQL_Latin1_General_CP1_CI_AS;
END
GO

ALTER DATABASE [ProCargo] SET READ_COMMITTED_SNAPSHOT ON WITH ROLLBACK IMMEDIATE;
GO
ALTER DATABASE [ProCargo] SET ALLOW_SNAPSHOT_ISOLATION ON;
GO
ALTER DATABASE [ProCargo] SET RECOVERY FULL;
GO

GO

USE [ProCargo];
GO

-- >>>>> 02-Schemas/001_CreateSchemas.sql
/*
    Schemas group objects by bounded context. They give us:
      * security boundaries: the application login is granted EXECUTE per schema and
        has NO direct table access (see 11-Security),
      * readability: every object name says which module owns it,
      * independent evolution of modules (e.g. moving fin to its own database later).

      sec  - identity, roles, permissions, tokens, login history
      mst  - master/reference data and system settings
      core - customers, owners, drivers, vehicles, bookings, quotations, trips, tracking, POD, files
      fin  - pricing, invoices, payments, refunds, settlements, commission
      sup  - complaints, support tickets, enquiries, notifications
      aud  - audit log
      rpt  - reporting views and report/dashboard procedures
*/
IF SCHEMA_ID(N'sec')  IS NULL EXEC (N'CREATE SCHEMA sec AUTHORIZATION dbo');
IF SCHEMA_ID(N'mst')  IS NULL EXEC (N'CREATE SCHEMA mst AUTHORIZATION dbo');
IF SCHEMA_ID(N'core') IS NULL EXEC (N'CREATE SCHEMA core AUTHORIZATION dbo');
IF SCHEMA_ID(N'fin')  IS NULL EXEC (N'CREATE SCHEMA fin AUTHORIZATION dbo');
IF SCHEMA_ID(N'sup')  IS NULL EXEC (N'CREATE SCHEMA sup AUTHORIZATION dbo');
IF SCHEMA_ID(N'aud')  IS NULL EXEC (N'CREATE SCHEMA aud AUTHORIZATION dbo');
IF SCHEMA_ID(N'rpt')  IS NULL EXEC (N'CREATE SCHEMA rpt AUTHORIZATION dbo');
GO

GO

-- >>>>> 03-Tables/005_Sequences.sql
/*
    Sequences used to generate human-readable business numbers (e.g. PC-BKG-2026-000125).
    NEXT VALUE FOR is atomic and concurrency-safe, unlike SELECT MAX(Id) + 1.
    Gaps are expected (rolled back transactions consume values) and are acceptable for business numbers.
*/
IF OBJECT_ID(N'core.seq_CustomerNumber',  N'SO') IS NULL CREATE SEQUENCE core.seq_CustomerNumber  AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 20;
IF OBJECT_ID(N'core.seq_OwnerNumber',     N'SO') IS NULL CREATE SEQUENCE core.seq_OwnerNumber     AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 20;
IF OBJECT_ID(N'core.seq_DriverNumber',    N'SO') IS NULL CREATE SEQUENCE core.seq_DriverNumber    AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 20;
IF OBJECT_ID(N'core.seq_BookingNumber',   N'SO') IS NULL CREATE SEQUENCE core.seq_BookingNumber   AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 50;
IF OBJECT_ID(N'core.seq_QuotationNumber', N'SO') IS NULL CREATE SEQUENCE core.seq_QuotationNumber AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 50;
IF OBJECT_ID(N'core.seq_TripNumber',      N'SO') IS NULL CREATE SEQUENCE core.seq_TripNumber      AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 50;
IF OBJECT_ID(N'fin.seq_InvoiceNumber',    N'SO') IS NULL CREATE SEQUENCE fin.seq_InvoiceNumber    AS BIGINT START WITH 1 INCREMENT BY 1 NO CACHE;
IF OBJECT_ID(N'fin.seq_PaymentNumber',    N'SO') IS NULL CREATE SEQUENCE fin.seq_PaymentNumber    AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 50;
IF OBJECT_ID(N'fin.seq_RefundNumber',     N'SO') IS NULL CREATE SEQUENCE fin.seq_RefundNumber     AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 20;
IF OBJECT_ID(N'fin.seq_SettlementNumber', N'SO') IS NULL CREATE SEQUENCE fin.seq_SettlementNumber AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 20;
IF OBJECT_ID(N'sup.seq_ComplaintNumber',  N'SO') IS NULL CREATE SEQUENCE sup.seq_ComplaintNumber  AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 20;
IF OBJECT_ID(N'sup.seq_TicketNumber',     N'SO') IS NULL CREATE SEQUENCE sup.seq_TicketNumber     AS BIGINT START WITH 1 INCREMENT BY 1 CACHE 20;
GO

GO

