        Longitude             DECIMAL(9,6)   NOT NULL CONSTRAINT CK_TripLocationHistory_Longitude CHECK (Longitude BETWEEN -180 AND 180),
        RecordedDateUtc       DATETIME2(3)   NOT NULL,
