        AdjustmentType     VARCHAR(20)    NOT NULL CONSTRAINT CK_PricingRule_AdjustmentType CHECK (AdjustmentType IN ('Percentage','Flat')),
        AdjustmentValue    DECIMAL(12,2)  NOT NULL,
