    @UserId             BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE core.CustomerContact
    SET IsDeleted = 1, ModifiedBy = @UserId, ModifiedDateUtc = SYSUTCDATETIME()
    WHERE CustomerContactId = @CustomerContactId AND CustomerId = @CustomerId AND IsDeleted = 0;

