/*
    Module: Drivers (schema core)
    Availability ids: 1 Available, 2 OnTrip, 3 OffDuty, 4 Unavailable. OnTrip is only set by trip procedures.
*/

CREATE OR ALTER PROCEDURE core.usp_Driver_GetPaged
    @PageNumber            INT,
    @PageSize              INT,
    @Search                NVARCHAR(100) = NULL,
    @OwnerId               BIGINT        = NULL,
    @VerificationStatusId  INT           = NULL,
    @AvailabilityStatusId  INT           = NULL,
    @IsActive              BIT           = NULL,
    @SortBy                VARCHAR(50)   = 'CreatedDate',
    @SortDirection         VARCHAR(4)    = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        d.DriverId,
        d.DriverNumber,
        d.OwnerId,
        o.FullName AS OwnerName,
        d.FullName,
        d.PhoneNumber,
        dl.LicenseNumber,
        dl.ExpiryDate AS LicenseExpiryDate,
        d.VerificationStatusId,
        d.AvailabilityStatusId,
        d.IsActive,
        d.CreatedDateUtc,
        COUNT(*) OVER () AS TotalRecords
    FROM core.Driver AS d
    LEFT JOIN core.VehicleOwner  AS o  ON o.OwnerId = d.OwnerId
    LEFT JOIN core.DriverLicense AS dl ON dl.DriverId = d.DriverId AND dl.IsCurrent = 1
    WHERE d.IsDeleted = 0
      AND (@OwnerId IS NULL OR d.OwnerId = @OwnerId)
      AND (@VerificationStatusId IS NULL OR d.VerificationStatusId = @VerificationStatusId)
      AND (@AvailabilityStatusId IS NULL OR d.AvailabilityStatusId = @AvailabilityStatusId)
      AND (@IsActive IS NULL OR d.IsActive = @IsActive)
      AND (@Search IS NULL
           OR d.DriverNumber LIKE @Search + '%'
           OR d.FullName LIKE N'%' + @Search + N'%'
           OR d.PhoneNumber LIKE @Search + '%'
           OR dl.LicenseNumber LIKE @Search + '%')
    ORDER BY
        CASE WHEN @SortBy = 'Name'        AND @SortDirection = 'ASC'  THEN d.FullName END ASC,
        CASE WHEN @SortBy = 'Name'        AND @SortDirection = 'DESC' THEN d.FullName END DESC,
        CASE WHEN @SortBy = 'LicenseExpiry' AND @SortDirection = 'ASC'  THEN dl.ExpiryDate END ASC,
        CASE WHEN @SortBy = 'LicenseExpiry' AND @SortDirection = 'DESC' THEN dl.ExpiryDate END DESC,
        CASE WHEN @SortBy = 'CreatedDate' AND @SortDirection = 'ASC'  THEN d.CreatedDateUtc END ASC,
        d.CreatedDateUtc DESC,
        d.DriverId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY
    OPTION (RECOMPILE);
END
GO

CREATE OR ALTER PROCEDURE core.usp_Driver_GetById
    @DriverId BIGINT = NULL,
    @UserId   BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        d.DriverId,
        d.UserId,
        d.DriverNumber,
        d.OwnerId,
        o.FullName AS OwnerName,
        d.FullName,
        u.Email,
        d.PhoneNumber,
        d.AlternatePhoneNumber,
        d.DateOfBirth,
        dl.LicenseNumber,
        dl.LicenseClass,
        dl.IssueDate          AS LicenseIssueDate,
        dl.ExpiryDate         AS LicenseExpiryDate,
        dl.IssuingAuthority   AS LicenseIssuingAuthority,
        d.VerificationStatusId,
        d.VerificationRemarks,
        d.VerifiedDateUtc,
        d.AvailabilityStatusId,
        d.IsActive,
        d.CreatedDateUtc,
        d.RowVersion
    FROM core.Driver AS d
    INNER JOIN sec.[User]        AS u  ON u.UserId = d.UserId
    LEFT  JOIN core.VehicleOwner AS o  ON o.OwnerId = d.OwnerId
    LEFT  JOIN core.DriverLicense AS dl ON dl.DriverId = d.DriverId AND dl.IsCurrent = 1
    WHERE d.IsDeleted = 0
      AND ((@DriverId IS NOT NULL AND d.DriverId = @DriverId)
        OR (@DriverId IS NULL AND d.UserId = @UserId));
END
GO

-- Owner / operations onboard a driver: creates the login (role Driver) and the driver profile.
CREATE OR ALTER PROCEDURE core.usp_Driver_CreateWithUser
    @OwnerId               BIGINT        = NULL,
    @FullName              NVARCHAR(150),
    @Email                 NVARCHAR(256),
    @NormalizedEmail       NVARCHAR(256),
    @PhoneNumber           VARCHAR(20),
    @AlternatePhoneNumber  VARCHAR(20),
    @DateOfBirth           DATE,
    @PasswordHash          NVARCHAR(500),
    @LicenseNumber         VARCHAR(20),
    @LicenseClass          VARCHAR(50),
    @LicenseIssueDate      DATE,
    @LicenseExpiryDate     DATE,
    @IssuingAuthority      NVARCHAR(100),
    @CreatedBy             BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF EXISTS (SELECT 1 FROM sec.[User] WHERE NormalizedEmail = @NormalizedEmail AND IsDeleted = 0)
        THROW 50409, N'EMAIL_ALREADY_REGISTERED|An account with this e-mail already exists.', 1;

    IF EXISTS (SELECT 1 FROM sec.[User] WHERE PhoneNumber = @PhoneNumber AND IsDeleted = 0)
        THROW 50409, N'PHONE_ALREADY_REGISTERED|An account with this phone number already exists.', 1;

    IF EXISTS (SELECT 1 FROM core.DriverLicense WHERE LicenseNumber = @LicenseNumber AND IsCurrent = 1)
        THROW 50409, N'LICENSE_ALREADY_REGISTERED|This licence number is already registered.', 1;

    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @UserId BIGINT, @DriverId BIGINT, @DriverNumber VARCHAR(30);

    BEGIN TRY
        BEGIN TRANSACTION;

        INSERT INTO sec.[User] (Email, NormalizedEmail, PhoneNumber, FullName, PasswordHash, IsInternal, MustChangePassword, CreatedBy)
        VALUES (@Email, @NormalizedEmail, @PhoneNumber, @FullName, @PasswordHash, 0, 1, @CreatedBy);
        SET @UserId = SCOPE_IDENTITY();

        INSERT INTO sec.UserRole (UserId, RoleId, CreatedBy)
        SELECT @UserId, r.RoleId, @CreatedBy FROM sec.Role AS r WHERE r.Name = 'Driver';

        SET @DriverNumber = core.fn_FormatBusinessNumber('DRV', NEXT VALUE FOR core.seq_DriverNumber, @Now);

        INSERT INTO core.Driver (UserId, DriverNumber, OwnerId, FullName, PhoneNumber, AlternatePhoneNumber, DateOfBirth, CreatedBy, CreatedDateUtc)
        VALUES (@UserId, @DriverNumber, @OwnerId, @FullName, @PhoneNumber, @AlternatePhoneNumber, @DateOfBirth, @CreatedBy, @Now);
        SET @DriverId = SCOPE_IDENTITY();

        INSERT INTO core.DriverLicense (DriverId, LicenseNumber, LicenseClass, IssueDate, ExpiryDate, IssuingAuthority, IsCurrent, CreatedBy)
        VALUES (@DriverId, UPPER(@LicenseNumber), @LicenseClass, @LicenseIssueDate, @LicenseExpiryDate, @IssuingAuthority, 1, @CreatedBy);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH

    SELECT @UserId AS UserId, @DriverId AS ProfileId, @DriverNumber AS ProfileNumber;
END
GO

CREATE OR ALTER PROCEDURE core.usp_Driver_Update
    @DriverId              BIGINT,
    @FullName              NVARCHAR(150),
    @PhoneNumber           VARCHAR(20),
    @AlternatePhoneNumber  VARCHAR(20),
    @DateOfBirth           DATE,
    @ModifiedBy            BIGINT,
    @RowVersion            BINARY(8)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @UserId BIGINT = (SELECT UserId FROM core.Driver WHERE DriverId = @DriverId AND IsDeleted = 0);
    IF @UserId IS NULL
        THROW 50404, N'DRIVER_NOT_FOUND|Driver was not found.', 1;

    IF EXISTS (SELECT 1 FROM sec.[User] WHERE PhoneNumber = @PhoneNumber AND UserId <> @UserId AND IsDeleted = 0)
        THROW 50409, N'PHONE_ALREADY_REGISTERED|Another account already uses this phone number.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE core.Driver
        SET FullName = @FullName, PhoneNumber = @PhoneNumber, AlternatePhoneNumber = @AlternatePhoneNumber,
            DateOfBirth = @DateOfBirth, ModifiedBy = @ModifiedBy, ModifiedDateUtc = SYSUTCDATETIME()
        WHERE DriverId = @DriverId AND RowVersion = @RowVersion;

        IF @@ROWCOUNT = 0
            THROW 50412, N'CONCURRENCY_CONFLICT|The driver was modified by someone else. Reload and try again.', 1;

        UPDATE sec.[User]
        SET FullName = @FullName, PhoneNumber = @PhoneNumber, ModifiedBy = @ModifiedBy, ModifiedDateUtc = SYSUTCDATETIME()
        WHERE UserId = @UserId;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE core.usp_Driver_SetLicense
    @DriverId          BIGINT,
    @LicenseNumber     VARCHAR(20),
    @LicenseClass      VARCHAR(50),
    @IssueDate         DATE,
    @ExpiryDate        DATE,
    @IssuingAuthority  NVARCHAR(100),
    @UserId            BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @LicenseNumber = UPPER(@LicenseNumber);

    IF NOT EXISTS (SELECT 1 FROM core.Driver WHERE DriverId = @DriverId AND IsDeleted = 0)
        THROW 50404, N'DRIVER_NOT_FOUND|Driver was not found.', 1;

    IF EXISTS (SELECT 1 FROM core.DriverLicense WHERE LicenseNumber = @LicenseNumber AND IsCurrent = 1 AND DriverId <> @DriverId)
        THROW 50409, N'LICENSE_ALREADY_REGISTERED|This licence number is already registered to another driver.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE core.DriverLicense SET IsCurrent = 0, ModifiedBy = @UserId, ModifiedDateUtc = SYSUTCDATETIME()
        WHERE DriverId = @DriverId AND IsCurrent = 1;

        INSERT INTO core.DriverLicense (DriverId, LicenseNumber, LicenseClass, IssueDate, ExpiryDate, IssuingAuthority, IsCurrent, CreatedBy)
        VALUES (@DriverId, @LicenseNumber, @LicenseClass, @IssueDate, @ExpiryDate, @IssuingAuthority, 1, @UserId);

        -- a changed licence must be re-verified
        UPDATE core.Driver
        SET VerificationStatusId = CASE WHEN VerificationStatusId = 3 THEN 2 ELSE VerificationStatusId END,
            ModifiedBy = @UserId, ModifiedDateUtc = SYSUTCDATETIME()
        WHERE DriverId = @DriverId;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE core.usp_Driver_SetAvailability
    @DriverId              BIGINT,
    @AvailabilityStatusId  INT,
    @Reason                NVARCHAR(300),
    @ChangedBy             BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @AvailabilityStatusId = 2
        THROW 50400, N'AVAILABILITY_INVALID|On-trip status is set automatically by trip assignment.', 1;

    BEGIN TRANSACTION;
        UPDATE core.Driver
        SET AvailabilityStatusId = @AvailabilityStatusId, ModifiedBy = @ChangedBy, ModifiedDateUtc = SYSUTCDATETIME()
        WHERE DriverId = @DriverId AND IsDeleted = 0 AND AvailabilityStatusId <> 2;

        IF @@ROWCOUNT = 0
        BEGIN
            ROLLBACK TRANSACTION;
            IF EXISTS (SELECT 1 FROM core.Driver WHERE DriverId = @DriverId AND IsDeleted = 0)
                THROW 50400, N'DRIVER_ON_TRIP|Availability cannot be changed while the driver is on a trip.', 1;
            THROW 50404, N'DRIVER_NOT_FOUND|Driver was not found.', 1;
        END

        INSERT INTO core.DriverAvailabilityHistory (DriverId, AvailabilityStatusId, Reason, ChangedBy)
        VALUES (@DriverId, @AvailabilityStatusId, @Reason, @ChangedBy);
    COMMIT TRANSACTION;
END
GO

CREATE OR ALTER PROCEDURE core.usp_Driver_SetVerification
    @DriverId              BIGINT,
    @VerificationStatusId  INT,
    @Remarks               NVARCHAR(500),
    @VerifiedBy            BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE core.Driver
    SET VerificationStatusId = @VerificationStatusId,
        VerificationRemarks = @Remarks,
        VerifiedBy = @VerifiedBy,
        VerifiedDateUtc = SYSUTCDATETIME(),
        AvailabilityStatusId = CASE WHEN @VerificationStatusId <> 3 AND AvailabilityStatusId = 1 THEN 4 ELSE AvailabilityStatusId END,
        ModifiedBy = @VerifiedBy,
        ModifiedDateUtc = SYSUTCDATETIME()
    WHERE DriverId = @DriverId AND IsDeleted = 0;

    IF @@ROWCOUNT = 0
        THROW 50404, N'DRIVER_NOT_FOUND|Driver was not found.', 1;
END
GO

CREATE OR ALTER PROCEDURE core.usp_Driver_SetActive
    @DriverId    BIGINT,
    @IsActive    BIT,
    @ModifiedBy  BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @UserId BIGINT = (SELECT UserId FROM core.Driver WHERE DriverId = @DriverId AND IsDeleted = 0);
    IF @UserId IS NULL
        THROW 50404, N'DRIVER_NOT_FOUND|Driver was not found.', 1;

    IF @IsActive = 0 AND EXISTS (SELECT 1 FROM core.Trip WHERE DriverId = @DriverId AND TripStatusId IN (1, 2, 3, 9, 10))
        THROW 50400, N'DRIVER_HAS_ACTIVE_TRIP|The driver has a trip in progress.', 1;

    BEGIN TRANSACTION;
        UPDATE core.Driver
        SET IsActive = @IsActive,
            AvailabilityStatusId = CASE WHEN @IsActive = 0 THEN 4 ELSE AvailabilityStatusId END,
            ModifiedBy = @ModifiedBy, ModifiedDateUtc = SYSUTCDATETIME()
        WHERE DriverId = @DriverId;

        UPDATE sec.[User] SET IsActive = @IsActive, ModifiedBy = @ModifiedBy, ModifiedDateUtc = SYSUTCDATETIME()
        WHERE UserId = @UserId;

        IF @IsActive = 0
            UPDATE sec.RefreshToken SET RevokedDateUtc = SYSUTCDATETIME(), RevokedReason = 'Deactivated'
            WHERE UserId = @UserId AND RevokedDateUtc IS NULL;
    COMMIT TRANSACTION;
END
GO

-- Verified, active, available drivers whose licence is valid on the planned date.
CREATE OR ALTER PROCEDURE core.usp_Driver_GetAvailableForAssignment
    @OwnerId      BIGINT = NULL,
    @OnDateUtc    DATETIME2(3)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        d.DriverId,
        d.DriverNumber,
        d.FullName,
        d.PhoneNumber,
        d.OwnerId,
        dl.ExpiryDate AS LicenseExpiryDate
    FROM core.Driver AS d
    INNER JOIN core.DriverLicense AS dl ON dl.DriverId = d.DriverId AND dl.IsCurrent = 1
    WHERE d.IsDeleted = 0
      AND d.IsActive = 1
      AND d.VerificationStatusId = 3
      AND d.AvailabilityStatusId = 1
      AND dl.ExpiryDate >= CAST(@OnDateUtc AS DATE)
      AND (@OwnerId IS NULL OR d.OwnerId = @OwnerId OR d.OwnerId IS NULL)
    ORDER BY CASE WHEN d.OwnerId = @OwnerId THEN 0 ELSE 1 END, d.FullName;
END
GO

GO

-- >>>>> 08-StoredProcedures/06_Vehicles.sql
/*
    Module: Vehicles (schema core)
    Vehicle numbers are stored normalised (upper case, no spaces/hyphens) by the API before calling.
*/

CREATE OR ALTER PROCEDURE core.usp_Vehicle_GetPaged
    @PageNumber            INT,
    @PageSize              INT,
    @Search                NVARCHAR(100) = NULL,
    @OwnerId               BIGINT        = NULL,
    @VehicleTypeId         INT           = NULL,
    @VerificationStatusId  INT           = NULL,
    @IsAvailable           BIT           = NULL,
    @IsActive              BIT           = NULL,
    @SortBy                VARCHAR(50)   = 'CreatedDate',
    @SortDirection         VARCHAR(4)    = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        v.VehicleId,
        v.VehicleNumber,
        v.OwnerId,
        o.FullName AS OwnerName,
        v.VehicleTypeId,
        vt.Name    AS VehicleTypeName,
        v.Manufacturer,
        v.Model,
        v.CapacityKg,
        v.VerificationStatusId,
        v.IsAvailable,
        v.IsActive,
        v.InsuranceExpiryDate,
        v.PermitExpiryDate,
        v.FitnessExpiryDate,
        v.CreatedDateUtc,
        COUNT(*) OVER () AS TotalRecords
    FROM core.Vehicle AS v
    INNER JOIN core.VehicleOwner AS o  ON o.OwnerId = v.OwnerId
    INNER JOIN mst.VehicleType   AS vt ON vt.VehicleTypeId = v.VehicleTypeId
    WHERE v.IsDeleted = 0
      AND (@OwnerId IS NULL OR v.OwnerId = @OwnerId)
      AND (@VehicleTypeId IS NULL OR v.VehicleTypeId = @VehicleTypeId)
      AND (@VerificationStatusId IS NULL OR v.VerificationStatusId = @VerificationStatusId)
      AND (@IsAvailable IS NULL OR v.IsAvailable = @IsAvailable)
      AND (@IsActive IS NULL OR v.IsActive = @IsActive)
      AND (@Search IS NULL OR v.VehicleNumber LIKE N'%' + @Search + N'%' OR o.FullName LIKE N'%' + @Search + N'%' OR v.Model LIKE N'%' + @Search + N'%')
    ORDER BY
        CASE WHEN @SortBy = 'VehicleNumber'   AND @SortDirection = 'ASC'  THEN v.VehicleNumber END ASC,
        CASE WHEN @SortBy = 'VehicleNumber'   AND @SortDirection = 'DESC' THEN v.VehicleNumber END DESC,
        CASE WHEN @SortBy = 'InsuranceExpiry' AND @SortDirection = 'ASC'  THEN v.InsuranceExpiryDate END ASC,
        CASE WHEN @SortBy = 'InsuranceExpiry' AND @SortDirection = 'DESC' THEN v.InsuranceExpiryDate END DESC,
        CASE WHEN @SortBy = 'CreatedDate'     AND @SortDirection = 'ASC'  THEN v.CreatedDateUtc END ASC,
        v.CreatedDateUtc DESC,
        v.VehicleId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY
    OPTION (RECOMPILE);
END
GO

CREATE OR ALTER PROCEDURE core.usp_Vehicle_GetById
    @VehicleId BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        v.VehicleId,
        v.OwnerId,
        o.FullName AS OwnerName,
        v.VehicleNumber,
        v.VehicleTypeId,
        vt.Name    AS VehicleTypeName,
        v.Manufacturer,
        v.Model,
        v.ManufactureYear,
        v.CapacityKg,
        v.PermitNumber,
        v.PermitExpiryDate,
        v.InsuranceNumber,
        v.InsuranceExpiryDate,
        v.FitnessExpiryDate,
        v.PucExpiryDate,
        v.VerificationStatusId,
        v.VerificationRemarks,
        v.VerifiedDateUtc,
        v.IsAvailable,
        v.IsActive,
        v.CreatedDateUtc,
        v.RowVersion
    FROM core.Vehicle AS v
    INNER JOIN core.VehicleOwner AS o  ON o.OwnerId = v.OwnerId
    INNER JOIN mst.VehicleType   AS vt ON vt.VehicleTypeId = v.VehicleTypeId
    WHERE v.VehicleId = @VehicleId AND v.IsDeleted = 0;
END
GO

CREATE OR ALTER PROCEDURE core.usp_Vehicle_Create
    @OwnerId              BIGINT,
    @VehicleNumber        VARCHAR(15),
    @VehicleTypeId        INT,
    @Manufacturer         NVARCHAR(100),
    @Model                NVARCHAR(100),
    @ManufactureYear      INT,
    @CapacityKg           DECIMAL(10,2),
    @PermitNumber         VARCHAR(50),
    @PermitExpiryDate     DATE,
    @InsuranceNumber      VARCHAR(50),
    @InsuranceExpiryDate  DATE,
    @FitnessExpiryDate    DATE,
    @PucExpiryDate        DATE,
    @CreatedBy            BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM core.Vehicle WHERE VehicleNumber = @VehicleNumber)
        THROW 50409, N'VEHICLE_NUMBER_EXISTS|A vehicle with this registration number already exists.', 1;

    IF NOT EXISTS (SELECT 1 FROM core.VehicleOwner WHERE OwnerId = @OwnerId AND IsDeleted = 0 AND IsActive = 1)
        THROW 50400, N'OWNER_INACTIVE|Vehicles can only be added for an active owner.', 1;

    INSERT INTO core.Vehicle
        (OwnerId, VehicleNumber, VehicleTypeId, Manufacturer, Model, ManufactureYear, CapacityKg, PermitNumber, PermitExpiryDate,
         InsuranceNumber, InsuranceExpiryDate, FitnessExpiryDate, PucExpiryDate, CreatedBy)
    VALUES
        (@OwnerId, @VehicleNumber, @VehicleTypeId, @Manufacturer, @Model, @ManufactureYear, @CapacityKg, @PermitNumber, @PermitExpiryDate,
         @InsuranceNumber, @InsuranceExpiryDate, @FitnessExpiryDate, @PucExpiryDate, @CreatedBy);

    SELECT CAST(SCOPE_IDENTITY() AS BIGINT) AS Id;
END
GO

CREATE OR ALTER PROCEDURE core.usp_Vehicle_Update
    @VehicleId            BIGINT,
    @VehicleTypeId        INT,
    @Manufacturer         NVARCHAR(100),
    @Model                NVARCHAR(100),
    @ManufactureYear      INT,
    @CapacityKg           DECIMAL(10,2),
    @PermitNumber         VARCHAR(50),
    @PermitExpiryDate     DATE,
    @InsuranceNumber      VARCHAR(50),
    @InsuranceExpiryDate  DATE,
    @FitnessExpiryDate    DATE,
    @PucExpiryDate        DATE,
    @ModifiedBy           BIGINT,
    @RowVersion           BINARY(8)
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE core.Vehicle
    SET VerificationStatusId =
            CASE WHEN VerificationStatusId = 3 AND (
                      VehicleTypeId <> @VehicleTypeId OR CapacityKg <> @CapacityKg
                   OR ISNULL(PermitNumber, '') <> ISNULL(@PermitNumber, '')
                   OR ISNULL(InsuranceNumber, '') <> ISNULL(@InsuranceNumber, ''))
                 THEN 2 ELSE VerificationStatusId END,
        VehicleTypeId = @VehicleTypeId,
        Manufacturer = @Manufacturer,
        Model = @Model,
        ManufactureYear = @ManufactureYear,
        CapacityKg = @CapacityKg,
        PermitNumber = @PermitNumber,
        PermitExpiryDate = @PermitExpiryDate,
        InsuranceNumber = @InsuranceNumber,
        InsuranceExpiryDate = @InsuranceExpiryDate,
        FitnessExpiryDate = @FitnessExpiryDate,
        PucExpiryDate = @PucExpiryDate,
        ModifiedBy = @ModifiedBy,
        ModifiedDateUtc = SYSUTCDATETIME()
    WHERE VehicleId = @VehicleId AND IsDeleted = 0 AND RowVersion = @RowVersion;

    IF @@ROWCOUNT = 0
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM core.Vehicle WHERE VehicleId = @VehicleId AND IsDeleted = 0)
            THROW 50404, N'VEHICLE_NOT_FOUND|Vehicle was not found.', 1;
        THROW 50412, N'CONCURRENCY_CONFLICT|The vehicle was modified by someone else. Reload and try again.', 1;
    END
END
GO

CREATE OR ALTER PROCEDURE core.usp_Vehicle_SetAvailability
    @VehicleId    BIGINT,
    @IsAvailable  BIT,
    @Reason       NVARCHAR(300),
    @ChangedBy    BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF EXISTS (SELECT 1 FROM core.Trip WHERE VehicleId = @VehicleId AND TripStatusId IN (1, 2, 3, 9, 10))
        THROW 50400, N'VEHICLE_ON_TRIP|Availability cannot be changed while the vehicle is assigned to a trip.', 1;

    IF @IsAvailable = 1 AND NOT EXISTS (SELECT 1 FROM core.Vehicle WHERE VehicleId = @VehicleId AND VerificationStatusId = 3 AND IsActive = 1 AND IsDeleted = 0)
        THROW 50400, N'VEHICLE_NOT_VERIFIED|Only verified, active vehicles can be marked available.', 1;

    BEGIN TRANSACTION;
        UPDATE core.Vehicle
        SET IsAvailable = @IsAvailable, ModifiedBy = @ChangedBy, ModifiedDateUtc = SYSUTCDATETIME()
        WHERE VehicleId = @VehicleId AND IsDeleted = 0;

        IF @@ROWCOUNT = 0
        BEGIN
            ROLLBACK TRANSACTION;
            THROW 50404, N'VEHICLE_NOT_FOUND|Vehicle was not found.', 1;
        END

        INSERT INTO core.VehicleAvailabilityHistory (VehicleId, IsAvailable, Reason, ChangedBy)
        VALUES (@VehicleId, @IsAvailable, @Reason, @ChangedBy);
    COMMIT TRANSACTION;
END
GO

CREATE OR ALTER PROCEDURE core.usp_Vehicle_SetVerification
    @VehicleId             BIGINT,
    @VerificationStatusId  INT,
    @Remarks               NVARCHAR(500),
    @VerifiedBy            BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE core.Vehicle
    SET VerificationStatusId = @VerificationStatusId,
        VerificationRemarks = @Remarks,
        VerifiedBy = @VerifiedBy,
        VerifiedDateUtc = SYSUTCDATETIME(),
        IsAvailable = CASE WHEN @VerificationStatusId = 3 THEN IsAvailable ELSE 0 END,
        ModifiedBy = @VerifiedBy,
        ModifiedDateUtc = SYSUTCDATETIME()
    WHERE VehicleId = @VehicleId AND IsDeleted = 0;

    IF @@ROWCOUNT = 0
        THROW 50404, N'VEHICLE_NOT_FOUND|Vehicle was not found.', 1;
END
GO

CREATE OR ALTER PROCEDURE core.usp_Vehicle_SetActive
    @VehicleId   BIGINT,
    @IsActive    BIT,
    @ModifiedBy  BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    IF @IsActive = 0 AND EXISTS (SELECT 1 FROM core.Trip WHERE VehicleId = @VehicleId AND TripStatusId IN (1, 2, 3, 9, 10))
        THROW 50400, N'VEHICLE_ON_TRIP|The vehicle is assigned to a trip in progress.', 1;

    UPDATE core.Vehicle
    SET IsActive = @IsActive,
        IsAvailable = CASE WHEN @IsActive = 0 THEN 0 ELSE IsAvailable END,
        ModifiedBy = @ModifiedBy, ModifiedDateUtc = SYSUTCDATETIME()
    WHERE VehicleId = @VehicleId AND IsDeleted = 0;

    IF @@ROWCOUNT = 0
        THROW 50404, N'VEHICLE_NOT_FOUND|Vehicle was not found.', 1;
END
GO

-- Candidates for trip assignment: verified, active, available, right type, enough capacity,
-- insurance valid on the planned pickup date.
CREATE OR ALTER PROCEDURE core.usp_Vehicle_GetAvailableForAssignment
    @VehicleTypeId  INT,
    @MinCapacityKg  DECIMAL(10,2),
    @OnDateUtc      DATETIME2(3)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        v.VehicleId,
        v.VehicleNumber,
        v.OwnerId,
        o.FullName AS OwnerName,
        v.VehicleTypeId,
        v.CapacityKg,
        v.InsuranceExpiryDate
    FROM core.Vehicle AS v
    INNER JOIN core.VehicleOwner AS o ON o.OwnerId = v.OwnerId AND o.IsActive = 1 AND o.VerificationStatusId = 3
    WHERE v.IsDeleted = 0
      AND v.IsActive = 1
      AND v.IsAvailable = 1
      AND v.VerificationStatusId = 3
      AND v.VehicleTypeId = @VehicleTypeId
      AND v.CapacityKg >= @MinCapacityKg
      AND (v.InsuranceExpiryDate IS NULL OR v.InsuranceExpiryDate >= CAST(@OnDateUtc AS DATE))
    ORDER BY v.CapacityKg, v.VehicleNumber;
END
GO

CREATE OR ALTER PROCEDURE core.usp_Vehicle_GetExpiring
    @WithinDays  INT,
    @OwnerId     BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        vc.VehicleId,
        vc.VehicleNumber,
        vc.OwnerId,
        vc.OwnerName,
        vc.InsuranceExpiryDate,
        vc.PermitExpiryDate,
        vc.FitnessExpiryDate,
        vc.PucExpiryDate,
        vc.NextExpiryDate,
        vc.DaysToNextExpiry
    FROM rpt.vw_VehicleCompliance AS vc
    WHERE vc.NextExpiryDate IS NOT NULL
      AND vc.DaysToNextExpiry <= @WithinDays
      AND (@OwnerId IS NULL OR vc.OwnerId = @OwnerId)
    ORDER BY vc.NextExpiryDate;
END
GO

