-- >>>>> 08-StoredProcedures/12_Invoices_Payments.sql
/*
    Module: Invoices, payments and refunds (schema fin)
    Invoice status: 1 Draft, 2 Issued, 3 PartiallyPaid, 4 Paid, 5 Cancelled
    Payment status: 1 Pending, 2 Initiated, 3 Authorized, 4 Paid, 5 Failed, 6 Refunded, 7 PartiallyRefunded, 8 PartiallyPaid, 9 Cancelled
    Refund status : 1 Pending, 2 Processed, 3 Failed

    Refunds are tracked against the payment (customer compensation / overcharge) and do NOT reopen the
    invoice; amount corrections to an invoice are made with invoice adjustments (credit lines).
*/

CREATE OR ALTER PROCEDURE fin.usp_Invoice_Create
    @BookingId          BIGINT,
    @PaymentTermsDays   INT,
    @CreatedBy          BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @TripId BIGINT, @TripStatusId INT, @CustomerId BIGINT, @QuotationId BIGINT;
    DECLARE @InvoiceId BIGINT, @InvoiceNumber VARCHAR(30);

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @CustomerId = b.CustomerId
        FROM core.Booking AS b WITH (UPDLOCK)
        WHERE b.BookingId = @BookingId AND b.BookingStatusId = 8;

        IF @CustomerId IS NULL
            THROW 50400, N'BOOKING_NOT_DELIVERED|Invoices can only be generated for delivered bookings.', 1;

        SELECT @TripId = t.TripId, @TripStatusId = t.TripStatusId, @QuotationId = t.QuotationId
        FROM core.Trip AS t WITH (UPDLOCK)
        WHERE t.BookingId = @BookingId AND t.TripStatusId <> 8;

        IF @TripStatusId IS NULL OR @TripStatusId <> 5
            THROW 50400, N'POD_REQUIRED|Proof of delivery must be uploaded before invoicing.', 1;

        IF EXISTS (SELECT 1 FROM fin.Invoice WHERE BookingId = @BookingId AND InvoiceStatusId <> 5)
            THROW 50409, N'INVOICE_EXISTS|An invoice already exists for this booking.', 1;

        SET @InvoiceNumber = core.fn_FormatBusinessNumber('INV', NEXT VALUE FOR fin.seq_InvoiceNumber, @Now);

        INSERT INTO fin.Invoice (InvoiceNumber, BookingId, TripId, CustomerId, QuotationId, InvoiceDateUtc, DueDateUtc, SubTotal, TaxPercent, TaxAmount, TotalAmount, InvoiceStatusId, CreatedBy, CreatedDateUtc)
        SELECT @InvoiceNumber, @BookingId, @TripId, @CustomerId, q.QuotationId, @Now, DATEADD(DAY, @PaymentTermsDays, @Now),
               q.SubTotal, q.TaxPercent, q.TaxAmount, q.TotalAmount, 2, @CreatedBy, @Now
        FROM core.Quotation AS q
        WHERE q.QuotationId = @QuotationId;
        SET @InvoiceId = SCOPE_IDENTITY();

        INSERT INTO fin.InvoiceItem (InvoiceId, ChargeCode, Description, Quantity, UnitRate, Amount, IsAdjustment, SortOrder, CreatedBy)
        SELECT @InvoiceId, qc.ChargeCode, qc.Description, qc.Quantity, qc.UnitRate, qc.Amount, 0, qc.SortOrder, @CreatedBy
        FROM core.QuotationCharge AS qc
        WHERE qc.QuotationId = @QuotationId;

        UPDATE core.Booking SET BookingStatusId = 9, ModifiedBy = @CreatedBy, ModifiedDateUtc = @Now WHERE BookingId = @BookingId;
        INSERT INTO core.BookingStatusHistory (BookingId, FromStatusId, ToStatusId, Remarks, ChangedBy, ChangedDateUtc)
        VALUES (@BookingId, 8, 9, N'Invoice ' + @InvoiceNumber + N' issued', @CreatedBy, @Now);

        UPDATE core.Trip SET TripStatusId = 6, ModifiedBy = @CreatedBy, ModifiedDateUtc = @Now WHERE TripId = @TripId;
        INSERT INTO core.TripStatusHistory (TripId, FromStatusId, ToStatusId, Remarks, ChangedBy, ChangedDateUtc)
        VALUES (@TripId, 5, 6, N'Invoiced', @CreatedBy, @Now);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH

    SELECT @InvoiceId AS Id, @InvoiceNumber AS Number;
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Invoice_GetById
    @InvoiceId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        i.InvoiceId,
        i.InvoiceNumber,
        i.BookingId,
        b.BookingNumber,
        i.TripId,
        t.TripNumber,
        i.CustomerId,
        c.FullName     AS CustomerName,
        c.CompanyName  AS CustomerCompanyName,
        c.GstNumber    AS CustomerGstNumber,
        c.Email        AS CustomerEmail,
        c.UserId       AS CustomerUserId,
        i.QuotationId,
        i.InvoiceDateUtc,
        i.DueDateUtc,
        i.SubTotal,
        i.TaxPercent,
        i.TaxAmount,
        i.TotalAmount,
        i.PaidAmount,
        CAST(i.TotalAmount - i.PaidAmount AS DECIMAL(14,2)) AS BalanceAmount,
        i.InvoiceStatusId,
        i.CancellationReason,
        i.CreatedDateUtc,
        i.RowVersion
    FROM fin.Invoice AS i
    INNER JOIN core.Booking  AS b ON b.BookingId = i.BookingId
    INNER JOIN core.Trip     AS t ON t.TripId = i.TripId
    INNER JOIN core.Customer AS c ON c.CustomerId = i.CustomerId
    WHERE i.InvoiceId = @InvoiceId;
END
GO

CREATE OR ALTER PROCEDURE fin.usp_InvoiceItem_GetByInvoice
    @InvoiceId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT ii.InvoiceItemId, ii.ChargeCode, ii.Description, ii.Quantity, ii.UnitRate, ii.Amount, ii.IsAdjustment, ii.SortOrder
    FROM fin.InvoiceItem AS ii
    WHERE ii.InvoiceId = @InvoiceId
    ORDER BY ii.SortOrder, ii.InvoiceItemId;
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Invoice_GetPaged
    @PageNumber       INT,
    @PageSize         INT,
    @Search           NVARCHAR(100) = NULL,
    @CustomerId       BIGINT        = NULL,
    @InvoiceStatusId  INT           = NULL,
    @OverdueOnly      BIT           = 0,
    @FromDateUtc      DATETIME2(3)  = NULL,
    @ToDateUtc        DATETIME2(3)  = NULL,
    @SortBy           VARCHAR(50)   = 'InvoiceDate',
    @SortDirection    VARCHAR(4)    = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();

    SELECT
        i.InvoiceId,
        i.InvoiceNumber,
        i.BookingId,
        b.BookingNumber,
        i.CustomerId,
        c.FullName AS CustomerName,
        i.InvoiceDateUtc,
        i.DueDateUtc,
        i.TotalAmount,
        i.PaidAmount,
        i.InvoiceStatusId,
        CAST(CASE WHEN i.InvoiceStatusId IN (2, 3) AND i.DueDateUtc < @Now THEN 1 ELSE 0 END AS BIT) AS IsOverdue,
        COUNT(*) OVER () AS TotalRecords
    FROM fin.Invoice AS i
    INNER JOIN core.Booking  AS b ON b.BookingId = i.BookingId
    INNER JOIN core.Customer AS c ON c.CustomerId = i.CustomerId
    WHERE (@CustomerId IS NULL OR i.CustomerId = @CustomerId)
      AND (@InvoiceStatusId IS NULL OR i.InvoiceStatusId = @InvoiceStatusId)
      AND (@OverdueOnly = 0 OR (i.InvoiceStatusId IN (2, 3) AND i.DueDateUtc < @Now))
      AND (@FromDateUtc IS NULL OR i.InvoiceDateUtc >= @FromDateUtc)
      AND (@ToDateUtc IS NULL OR i.InvoiceDateUtc < @ToDateUtc)
      AND (@Search IS NULL OR i.InvoiceNumber LIKE @Search + '%' OR b.BookingNumber LIKE @Search + '%' OR c.FullName LIKE N'%' + @Search + N'%')
    ORDER BY
        CASE WHEN @SortBy = 'DueDate'     AND @SortDirection = 'ASC'  THEN i.DueDateUtc END ASC,
        CASE WHEN @SortBy = 'DueDate'     AND @SortDirection = 'DESC' THEN i.DueDateUtc END DESC,
        CASE WHEN @SortBy = 'Total'       AND @SortDirection = 'ASC'  THEN i.TotalAmount END ASC,
        CASE WHEN @SortBy = 'Total'       AND @SortDirection = 'DESC' THEN i.TotalAmount END DESC,
        CASE WHEN @SortBy = 'InvoiceDate' AND @SortDirection = 'ASC'  THEN i.InvoiceDateUtc END ASC,
        i.InvoiceDateUtc DESC,
        i.InvoiceId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY
    OPTION (RECOMPILE);
END
GO

-- Adds a signed adjustment line (e.g. waiting charges incurred, goodwill credit) and recalculates totals.
CREATE OR ALTER PROCEDURE fin.usp_Invoice_AddAdjustment
    @InvoiceId    BIGINT,
    @Description  NVARCHAR(200),
    @Amount       DECIMAL(14,2),
    @CreatedBy    BIGINT,
    @RowVersion   BINARY(8)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM fin.Invoice WITH (UPDLOCK) WHERE InvoiceId = @InvoiceId AND RowVersion = @RowVersion)
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM fin.Invoice WHERE InvoiceId = @InvoiceId)
                THROW 50404, N'INVOICE_NOT_FOUND|Invoice was not found.', 1;
            THROW 50412, N'CONCURRENCY_CONFLICT|The invoice was modified by someone else. Reload and try again.', 1;
        END

        IF NOT EXISTS (SELECT 1 FROM fin.Invoice WHERE InvoiceId = @InvoiceId AND InvoiceStatusId IN (2, 3))
            THROW 50400, N'INVOICE_NOT_ADJUSTABLE|Only issued or partially paid invoices can be adjusted.', 1;

        INSERT INTO fin.InvoiceItem (InvoiceId, ChargeCode, Description, Quantity, UnitRate, Amount, IsAdjustment, SortOrder, CreatedBy)
        VALUES (@InvoiceId, 'ADJUSTMENT', @Description, 1, @Amount, @Amount, 1, 1000, @CreatedBy);

        DECLARE @SubTotal DECIMAL(14,2) = (SELECT SUM(Amount) FROM fin.InvoiceItem WHERE InvoiceId = @InvoiceId AND ChargeCode <> 'TAX');

        UPDATE fin.Invoice
        SET SubTotal = @SubTotal,
            TaxAmount = ROUND(@SubTotal * TaxPercent / 100, 2),
            TotalAmount = @SubTotal + ROUND(@SubTotal * TaxPercent / 100, 2),
            ModifiedBy = @CreatedBy,
            ModifiedDateUtc = SYSUTCDATETIME()
        WHERE InvoiceId = @InvoiceId;

        IF EXISTS (SELECT 1 FROM fin.Invoice WHERE InvoiceId = @InvoiceId AND (TotalAmount < PaidAmount OR SubTotal < 0))
            THROW 50400, N'ADJUSTMENT_INVALID|The adjustment would make the invoice total lower than the amount already paid.', 1;

        UPDATE fin.Invoice
        SET InvoiceStatusId = CASE WHEN PaidAmount = 0 THEN 2 WHEN PaidAmount < TotalAmount THEN 3 ELSE 4 END
        WHERE InvoiceId = @InvoiceId;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Invoice_Cancel
    @InvoiceId   BIGINT,
    @Reason      NVARCHAR(500),
    @ModifiedBy  BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @BookingId BIGINT, @TripId BIGINT;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE fin.Invoice
        SET @BookingId = BookingId, @TripId = TripId, InvoiceStatusId = 5, CancellationReason = @Reason,
            ModifiedBy = @ModifiedBy, ModifiedDateUtc = @Now
        WHERE InvoiceId = @InvoiceId AND InvoiceStatusId = 2 AND PaidAmount = 0;

        IF @@ROWCOUNT = 0
            THROW 50400, N'INVOICE_NOT_CANCELLABLE|Only unpaid issued invoices can be cancelled.', 1;

        -- re-open billing: booking back to Delivered, trip back to PodUploaded
        UPDATE core.Booking SET BookingStatusId = 8, ModifiedBy = @ModifiedBy, ModifiedDateUtc = @Now WHERE BookingId = @BookingId AND BookingStatusId = 9;
        INSERT INTO core.BookingStatusHistory (BookingId, FromStatusId, ToStatusId, Remarks, ChangedBy, ChangedDateUtc)
        VALUES (@BookingId, 9, 8, N'Invoice cancelled: ' + @Reason, @ModifiedBy, @Now);

        UPDATE core.Trip SET TripStatusId = 5, ModifiedBy = @ModifiedBy, ModifiedDateUtc = @Now WHERE TripId = @TripId AND TripStatusId = 6;
        INSERT INTO core.TripStatusHistory (TripId, FromStatusId, ToStatusId, Remarks, ChangedBy, ChangedDateUtc)
        VALUES (@TripId, 6, 5, N'Invoice cancelled', @ModifiedBy, @Now);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO

-- Internal helper: applies a PAID payment to its invoice and moves the booking to Paid when settled in full.
-- Must be called inside the caller's transaction.
CREATE OR ALTER PROCEDURE fin.usp_Payment_ApplyToInvoice
    @PaymentId  BIGINT,
    @ChangedBy  BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @InvoiceId BIGINT, @Amount DECIMAL(14,2), @BookingId BIGINT, @NewStatus INT, @Now DATETIME2(3) = SYSUTCDATETIME();
    SELECT @InvoiceId = InvoiceId, @Amount = Amount, @BookingId = BookingId FROM fin.Payment WHERE PaymentId = @PaymentId;

    UPDATE fin.Invoice
    SET PaidAmount = PaidAmount + @Amount,
        @NewStatus = InvoiceStatusId = CASE WHEN PaidAmount + @Amount >= TotalAmount THEN 4 ELSE 3 END,
        ModifiedBy = @ChangedBy,
        ModifiedDateUtc = @Now
    WHERE InvoiceId = @InvoiceId AND InvoiceStatusId IN (2, 3) AND PaidAmount + @Amount <= TotalAmount;

    IF @@ROWCOUNT = 0
        THROW 50400, N'PAYMENT_EXCEEDS_BALANCE|The payment exceeds the outstanding invoice balance.', 1;

    IF @NewStatus = 4
    BEGIN
        UPDATE core.Booking SET BookingStatusId = 10, ModifiedBy = @ChangedBy, ModifiedDateUtc = @Now
        WHERE BookingId = @BookingId AND BookingStatusId = 9;

        IF @@ROWCOUNT > 0
            INSERT INTO core.BookingStatusHistory (BookingId, FromStatusId, ToStatusId, Remarks, ChangedBy, ChangedDateUtc)
            VALUES (@BookingId, 9, 10, N'Invoice paid in full', @ChangedBy, @Now);
    END
END
GO

/*
    Creates a payment. Idempotent per (CustomerId, IdempotencyKey): repeating the same request returns the
    original payment with IsExisting = 1 instead of creating a duplicate.
    @PaymentStatusId = 2 (Initiated) for online payments, 4 (Paid) for payments recorded by finance.
*/
CREATE OR ALTER PROCEDURE fin.usp_Payment_Create
    @InvoiceId        BIGINT,
    @Amount           DECIMAL(14,2),
    @PaymentMethodId  INT,
    @PaymentStatusId  INT,
    @GatewayName      VARCHAR(50),
    @IdempotencyKey   VARCHAR(100),
    @ReferenceNumber  VARCHAR(100),
    @Remarks          NVARCHAR(500),
    @CreatedBy        BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @CustomerId BIGINT, @BookingId BIGINT, @Balance DECIMAL(14,2);
    DECLARE @PaymentId BIGINT, @PaymentNumber VARCHAR(30), @IsExisting BIT = 0;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @CustomerId = CustomerId, @BookingId = BookingId, @Balance = TotalAmount - PaidAmount
        FROM fin.Invoice WITH (UPDLOCK)
        WHERE InvoiceId = @InvoiceId AND InvoiceStatusId IN (2, 3);

        IF @CustomerId IS NULL
            THROW 50400, N'INVOICE_NOT_PAYABLE|The invoice is not open for payment.', 1;

        IF @IdempotencyKey IS NOT NULL
            SELECT @PaymentId = PaymentId, @PaymentNumber = PaymentNumber
            FROM fin.Payment WHERE CustomerId = @CustomerId AND IdempotencyKey = @IdempotencyKey;

        IF @PaymentId IS NOT NULL
            SET @IsExisting = 1;
        ELSE
        BEGIN
            IF @Amount > @Balance
                THROW 50400, N'PAYMENT_EXCEEDS_BALANCE|The payment exceeds the outstanding invoice balance.', 1;

            SET @PaymentNumber = core.fn_FormatBusinessNumber('PAY', NEXT VALUE FOR fin.seq_PaymentNumber, @Now);

            INSERT INTO fin.Payment (PaymentNumber, InvoiceId, BookingId, CustomerId, Amount, PaymentMethodId, PaymentStatusId, GatewayName,
                                     ReferenceNumber, IdempotencyKey, PaymentDateUtc, Remarks, CreatedBy, CreatedDateUtc)
            VALUES (@PaymentNumber, @InvoiceId, @BookingId, @CustomerId, @Amount, @PaymentMethodId, @PaymentStatusId, @GatewayName,
                    @ReferenceNumber, @IdempotencyKey, CASE WHEN @PaymentStatusId = 4 THEN @Now ELSE NULL END, @Remarks, @CreatedBy, @Now);
            SET @PaymentId = SCOPE_IDENTITY();

            INSERT INTO fin.PaymentAttempt (PaymentId, AttemptNo, Status, ResponseMessage)
            VALUES (@PaymentId, 1, CASE WHEN @PaymentStatusId = 4 THEN 'RecordedOffline' ELSE 'Initiated' END, NULL);

            IF @PaymentStatusId = 4
                EXEC fin.usp_Payment_ApplyToInvoice @PaymentId = @PaymentId, @ChangedBy = @CreatedBy;
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH

    SELECT @PaymentId AS Id, @PaymentNumber AS Number, @IsExisting AS IsExisting;
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Payment_SetGatewayOrder
    @PaymentId       BIGINT,
    @GatewayOrderId  VARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE fin.Payment SET GatewayOrderId = @GatewayOrderId, ModifiedDateUtc = SYSUTCDATETIME()
    WHERE PaymentId = @PaymentId AND GatewayOrderId IS NULL;
END
GO

/*
    Gateway callback / webhook / manual status update. Idempotent per @GatewayEventId.
    Returns WasDuplicate = 1 (and changes nothing) when the event was already processed.
*/
CREATE OR ALTER PROCEDURE fin.usp_Payment_UpdateStatus
    @PaymentId             BIGINT,
    @NewStatusId           INT,
    @GatewayTransactionId  VARCHAR(100),
    @GatewayEventId        VARCHAR(100),
    @ResponseCode          VARCHAR(50),
    @ResponseMessage       NVARCHAR(500),
    @ModifiedBy            BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @CurrentStatusId INT, @WasDuplicate BIT = 0;

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @CurrentStatusId = PaymentStatusId FROM fin.Payment WITH (UPDLOCK) WHERE PaymentId = @PaymentId;
        IF @CurrentStatusId IS NULL
            THROW 50404, N'PAYMENT_NOT_FOUND|Payment was not found.', 1;

        IF @GatewayEventId IS NOT NULL AND EXISTS (SELECT 1 FROM fin.PaymentAttempt WHERE GatewayEventId = @GatewayEventId)
            SET @WasDuplicate = 1;
        ELSE IF @CurrentStatusId IN (4, 6, 7, 9) AND @NewStatusId <> @CurrentStatusId
            THROW 50409, N'PAYMENT_ALREADY_FINAL|The payment is already in a final state.', 1;
        ELSE IF @CurrentStatusId = @NewStatusId
            SET @WasDuplicate = 1;
        ELSE
        BEGIN
            INSERT INTO fin.PaymentAttempt (PaymentId, AttemptNo, GatewayEventId, Status, ResponseCode, ResponseMessage, CreatedDateUtc)
            SELECT @PaymentId, ISNULL(MAX(AttemptNo), 0) + 1, @GatewayEventId,
                   (SELECT Code FROM mst.PaymentStatus WHERE PaymentStatusId = @NewStatusId), @ResponseCode, @ResponseMessage, @Now
            FROM fin.PaymentAttempt WHERE PaymentId = @PaymentId;

            UPDATE fin.Payment
            SET PaymentStatusId = @NewStatusId,
                GatewayTransactionId = ISNULL(@GatewayTransactionId, GatewayTransactionId),
                PaymentDateUtc = CASE WHEN @NewStatusId = 4 THEN @Now ELSE PaymentDateUtc END,
                FailureReason = CASE WHEN @NewStatusId = 5 THEN @ResponseMessage ELSE FailureReason END,
                ModifiedBy = @ModifiedBy,
                ModifiedDateUtc = @Now
            WHERE PaymentId = @PaymentId;

            IF @NewStatusId = 4
                EXEC fin.usp_Payment_ApplyToInvoice @PaymentId = @PaymentId, @ChangedBy = @ModifiedBy;
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH

    SELECT @PaymentId AS Id, @WasDuplicate AS IsExisting;
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Payment_GetById
    @PaymentId       BIGINT       = NULL,
    @GatewayName     VARCHAR(50)  = NULL,
    @GatewayOrderId  VARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        p.PaymentId,
        p.PaymentNumber,
        p.InvoiceId,
        i.InvoiceNumber,
        p.BookingId,
        b.BookingNumber,
        p.CustomerId,
        c.FullName AS CustomerName,
        c.UserId AS CustomerUserId,
        c.Email AS CustomerEmail,
        p.Amount,
        p.RefundedAmount,
        p.PaymentMethodId,
        p.PaymentStatusId,
        p.GatewayName,
        p.GatewayOrderId,
        p.GatewayTransactionId,
        p.ReferenceNumber,
        p.PaymentDateUtc,
        p.FailureReason,
        p.Remarks,
        p.CreatedDateUtc
    FROM fin.Payment AS p
    INNER JOIN fin.Invoice   AS i ON i.InvoiceId = p.InvoiceId
    INNER JOIN core.Booking  AS b ON b.BookingId = p.BookingId
    INNER JOIN core.Customer AS c ON c.CustomerId = p.CustomerId
    WHERE (@PaymentId IS NOT NULL AND p.PaymentId = @PaymentId)
       OR (@PaymentId IS NULL AND p.GatewayName = @GatewayName AND p.GatewayOrderId = @GatewayOrderId);
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Payment_GetPaged
    @PageNumber       INT,
    @PageSize         INT,
    @Search           NVARCHAR(100) = NULL,
    @CustomerId       BIGINT        = NULL,
    @InvoiceId        BIGINT        = NULL,
    @PaymentStatusId  INT           = NULL,
    @PaymentMethodId  INT           = NULL,
    @FromDateUtc      DATETIME2(3)  = NULL,
    @ToDateUtc        DATETIME2(3)  = NULL,
    @SortBy           VARCHAR(50)   = 'CreatedDate',
    @SortDirection    VARCHAR(4)    = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        p.PaymentId,
        p.PaymentNumber,
        p.InvoiceId,
        i.InvoiceNumber,
        p.CustomerId,
        c.FullName AS CustomerName,
        p.Amount,
        p.RefundedAmount,
        p.PaymentMethodId,
        p.PaymentStatusId,
        p.GatewayName,
        p.PaymentDateUtc,
        p.CreatedDateUtc,
        COUNT(*) OVER () AS TotalRecords
    FROM fin.Payment AS p
    INNER JOIN fin.Invoice   AS i ON i.InvoiceId = p.InvoiceId
    INNER JOIN core.Customer AS c ON c.CustomerId = p.CustomerId
    WHERE (@CustomerId IS NULL OR p.CustomerId = @CustomerId)
      AND (@InvoiceId IS NULL OR p.InvoiceId = @InvoiceId)
      AND (@PaymentStatusId IS NULL OR p.PaymentStatusId = @PaymentStatusId)
      AND (@PaymentMethodId IS NULL OR p.PaymentMethodId = @PaymentMethodId)
      AND (@FromDateUtc IS NULL OR p.CreatedDateUtc >= @FromDateUtc)
      AND (@ToDateUtc IS NULL OR p.CreatedDateUtc < @ToDateUtc)
      AND (@Search IS NULL OR p.PaymentNumber LIKE @Search + '%' OR i.InvoiceNumber LIKE @Search + '%'
           OR p.GatewayTransactionId LIKE @Search + '%' OR p.ReferenceNumber LIKE @Search + '%' OR c.FullName LIKE N'%' + @Search + N'%')
    ORDER BY
        CASE WHEN @SortBy = 'Amount'      AND @SortDirection = 'ASC'  THEN p.Amount END ASC,
        CASE WHEN @SortBy = 'Amount'      AND @SortDirection = 'DESC' THEN p.Amount END DESC,
        CASE WHEN @SortBy = 'CreatedDate' AND @SortDirection = 'ASC'  THEN p.CreatedDateUtc END ASC,
        p.CreatedDateUtc DESC,
        p.PaymentId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY
    OPTION (RECOMPILE);
END
GO

CREATE OR ALTER PROCEDURE fin.usp_PaymentRefund_Create
    @PaymentId  BIGINT,
    @Amount     DECIMAL(14,2),
    @Reason     NVARCHAR(500),
    @CreatedBy  BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @Refundable DECIMAL(14,2), @RefundId BIGINT, @RefundNumber VARCHAR(30);

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @Refundable = p.Amount - p.RefundedAmount
               - ISNULL((SELECT SUM(r.Amount) FROM fin.PaymentRefund AS r WHERE r.PaymentId = p.PaymentId AND r.RefundStatusId = 1), 0)
        FROM fin.Payment AS p WITH (UPDLOCK)
        WHERE p.PaymentId = @PaymentId AND p.PaymentStatusId IN (4, 7);

        IF @Refundable IS NULL
            THROW 50400, N'PAYMENT_NOT_REFUNDABLE|Only paid payments can be refunded.', 1;

        IF @Amount > @Refundable
            THROW 50400, N'REFUND_EXCEEDS_PAYMENT|The refund exceeds the refundable amount.', 1;

        SET @RefundNumber = core.fn_FormatBusinessNumber('RFD', NEXT VALUE FOR fin.seq_RefundNumber, @Now);

        INSERT INTO fin.PaymentRefund (RefundNumber, PaymentId, Amount, Reason, RefundStatusId, CreatedBy, CreatedDateUtc)
        VALUES (@RefundNumber, @PaymentId, @Amount, @Reason, 1, @CreatedBy, @Now);
        SET @RefundId = SCOPE_IDENTITY();

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH

    SELECT @RefundId AS Id, @RefundNumber AS Number;
END
GO

CREATE OR ALTER PROCEDURE fin.usp_PaymentRefund_Complete
    @PaymentRefundId  BIGINT,
    @IsSuccess        BIT,
    @GatewayRefundId  VARCHAR(100),
    @FailureReason    NVARCHAR(500),
    @ModifiedBy       BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @PaymentId BIGINT, @Amount DECIMAL(14,2);

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE fin.PaymentRefund
        SET @PaymentId = PaymentId, @Amount = Amount,
            RefundStatusId = CASE WHEN @IsSuccess = 1 THEN 2 ELSE 3 END,
            GatewayRefundId = @GatewayRefundId,
            FailureReason = CASE WHEN @IsSuccess = 1 THEN NULL ELSE @FailureReason END,
            ProcessedDateUtc = @Now,
            ModifiedBy = @ModifiedBy,
            ModifiedDateUtc = @Now
        WHERE PaymentRefundId = @PaymentRefundId AND RefundStatusId = 1;

        IF @@ROWCOUNT = 0
            THROW 50400, N'REFUND_NOT_PENDING|The refund is not pending.', 1;

        IF @IsSuccess = 1
            UPDATE fin.Payment
            SET RefundedAmount = RefundedAmount + @Amount,
                PaymentStatusId = CASE WHEN RefundedAmount + @Amount >= Amount THEN 6 ELSE 7 END,
                ModifiedBy = @ModifiedBy,
                ModifiedDateUtc = @Now
            WHERE PaymentId = @PaymentId;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE fin.usp_PaymentRefund_GetByPayment
    @PaymentId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT r.PaymentRefundId, r.RefundNumber, r.PaymentId, r.Amount, r.Reason, r.RefundStatusId, r.GatewayRefundId,
           r.ProcessedDateUtc, r.FailureReason, r.CreatedDateUtc
    FROM fin.PaymentRefund AS r
    WHERE r.PaymentId = @PaymentId
    ORDER BY r.CreatedDateUtc DESC;
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Payment_GetReconciliation
    @FromUtc DATETIME2(3),
    @ToUtc   DATETIME2(3)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        p.PaymentMethodId,
        pm.Name AS PaymentMethodName,
        p.GatewayName,
        COUNT(*) AS PaymentCount,
        CAST(SUM(CASE WHEN p.PaymentStatusId IN (4, 6, 7) THEN p.Amount ELSE 0 END) AS DECIMAL(14,2)) AS CollectedAmount,
        CAST(SUM(p.RefundedAmount) AS DECIMAL(14,2)) AS RefundedAmount,
        CAST(SUM(CASE WHEN p.PaymentStatusId IN (4, 6, 7) THEN p.Amount ELSE 0 END) - SUM(p.RefundedAmount) AS DECIMAL(14,2)) AS NetAmount,
        SUM(CASE WHEN p.PaymentStatusId = 5 THEN 1 ELSE 0 END) AS FailedCount,
        SUM(CASE WHEN p.PaymentStatusId IN (1, 2, 3) THEN 1 ELSE 0 END) AS PendingCount
    FROM fin.Payment AS p
    INNER JOIN mst.PaymentMethod AS pm ON pm.PaymentMethodId = p.PaymentMethodId
    WHERE p.CreatedDateUtc >= @FromUtc AND p.CreatedDateUtc < @ToUtc
    GROUP BY p.PaymentMethodId, pm.Name, p.GatewayName
    ORDER BY CollectedAmount DESC;
END
GO

GO

-- >>>>> 08-StoredProcedures/13_Settlements.sql
/*
    Module: Owner settlements (schema fin)
    Settlement status: 1 Pending, 2 Approved, 3 Processing, 4 Completed, 5 Failed, 6 Cancelled

    Gross       = invoice sub-total (freight before tax) of the trip's booking
    Commission  = max(Gross * CommissionPercent, MinimumCommission), never more than Gross
    Tax (TDS)   = (Gross - Commission) * TdsPercent
    Net         = Gross - Commission - Tax + Adjustments
    Commission and TDS percentages are resolved by the API from fin.CommissionRule / mst.SystemSetting.
*/

CREATE OR ALTER PROCEDURE fin.usp_Settlement_Create
    @TripId             BIGINT,
    @CommissionPercent  DECIMAL(5,2),
    @MinimumCommission  DECIMAL(12,2),
    @TdsPercent         DECIMAL(5,2),
    @CreatedBy          BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @OwnerId BIGINT, @Gross DECIMAL(14,2), @TripNumber VARCHAR(30);
    DECLARE @Commission DECIMAL(14,2), @Tax DECIMAL(14,2), @Net DECIMAL(14,2), @BankAccountId BIGINT;
    DECLARE @SettlementId BIGINT, @SettlementNumber VARCHAR(30);

    BEGIN TRY
        BEGIN TRANSACTION;

        SELECT @OwnerId = t.OwnerId, @Gross = i.SubTotal, @TripNumber = t.TripNumber
        FROM core.Trip AS t WITH (UPDLOCK)
        INNER JOIN fin.Invoice AS i ON i.TripId = t.TripId AND i.InvoiceStatusId = 4
        WHERE t.TripId = @TripId AND t.TripStatusId = 6;

        IF @OwnerId IS NULL
            THROW 50400, N'TRIP_NOT_SETTLEABLE|A settlement needs a completed trip whose invoice is fully paid.', 1;

        IF EXISTS (SELECT 1 FROM fin.Settlement WHERE TripId = @TripId AND SettlementStatusId NOT IN (5, 6))
            THROW 50409, N'SETTLEMENT_EXISTS|A settlement already exists for this trip.', 1;

        SET @Commission = ROUND(@Gross * @CommissionPercent / 100, 2);
        IF @Commission < @MinimumCommission SET @Commission = @MinimumCommission;
        IF @Commission > @Gross SET @Commission = @Gross;
        SET @Tax = ROUND((@Gross - @Commission) * @TdsPercent / 100, 2);
        SET @Net = @Gross - @Commission - @Tax;

        SELECT TOP (1) @BankAccountId = OwnerBankAccountId
        FROM core.OwnerBankAccount
        WHERE OwnerId = @OwnerId AND IsActive = 1
        ORDER BY IsPrimary DESC, CASE WHEN VerificationStatusId = 3 THEN 0 ELSE 1 END, CreatedDateUtc DESC;

        SET @SettlementNumber = core.fn_FormatBusinessNumber('STL', NEXT VALUE FOR fin.seq_SettlementNumber, @Now);

        INSERT INTO fin.Settlement (SettlementNumber, TripId, OwnerId, OwnerBankAccountId, GrossAmount, CommissionPercent, CommissionAmount,
                                    TaxAmount, AdjustmentAmount, NetAmount, SettlementStatusId, CreatedBy, CreatedDateUtc)
        VALUES (@SettlementNumber, @TripId, @OwnerId, @BankAccountId, @Gross, @CommissionPercent, @Commission,
                @Tax, 0, @Net, 1, @CreatedBy, @Now);
        SET @SettlementId = SCOPE_IDENTITY();

        INSERT INTO fin.SettlementItem (SettlementId, ItemType, Description, Amount, SortOrder, CreatedBy)
        VALUES (@SettlementId, 'Freight',    N'Freight for trip ' + @TripNumber, @Gross, 1, @CreatedBy),
               (@SettlementId, 'Commission', N'Platform commission (' + CAST(@CommissionPercent AS NVARCHAR(10)) + N'%)', -@Commission, 2, @CreatedBy),
               (@SettlementId, 'Tax',        N'TDS (' + CAST(@TdsPercent AS NVARCHAR(10)) + N'%)', -@Tax, 3, @CreatedBy);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH

    SELECT @SettlementId AS Id, @SettlementNumber AS Number;
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Settlement_AddAdjustment
    @SettlementId  BIGINT,
    @Description   NVARCHAR(200),
    @Amount        DECIMAL(14,2),
    @CreatedBy     BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE fin.Settlement
        SET AdjustmentAmount = AdjustmentAmount + @Amount,
            NetAmount = NetAmount + @Amount,
            ModifiedBy = @CreatedBy,
            ModifiedDateUtc = SYSUTCDATETIME()
        WHERE SettlementId = @SettlementId AND SettlementStatusId = 1 AND NetAmount + @Amount >= 0;

        IF @@ROWCOUNT = 0
            THROW 50400, N'SETTLEMENT_NOT_ADJUSTABLE|Only pending settlements can be adjusted and the net amount cannot become negative.', 1;

        INSERT INTO fin.SettlementItem (SettlementId, ItemType, Description, Amount, SortOrder, CreatedBy)
        VALUES (@SettlementId, 'Adjustment', @Description, @Amount, 100, @CreatedBy);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO

-- Approve (1->2), process (2->3), fail (3->5), cancel (1/2->6), retry processing (5->3 is not allowed: create a new settlement).
CREATE OR ALTER PROCEDURE fin.usp_Settlement_ChangeStatus
    @SettlementId      BIGINT,
    @ExpectedStatusId  INT,
    @NewStatusId       INT,
    @Remarks           NVARCHAR(500),
    @ChangedBy         BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    IF @NewStatusId = 3 AND EXISTS (SELECT 1 FROM fin.Settlement WHERE SettlementId = @SettlementId AND OwnerBankAccountId IS NULL)
    BEGIN
        -- pick up a bank account the owner may have added after the settlement was created
        UPDATE s SET OwnerBankAccountId =
            (SELECT TOP (1) ba.OwnerBankAccountId FROM core.OwnerBankAccount AS ba
             WHERE ba.OwnerId = s.OwnerId AND ba.IsActive = 1 ORDER BY ba.IsPrimary DESC, ba.CreatedDateUtc DESC)
        FROM fin.Settlement AS s WHERE s.SettlementId = @SettlementId;

        IF EXISTS (SELECT 1 FROM fin.Settlement WHERE SettlementId = @SettlementId AND OwnerBankAccountId IS NULL)
            THROW 50400, N'OWNER_BANK_ACCOUNT_REQUIRED|The owner has no active bank account to pay into.', 1;
    END

    UPDATE fin.Settlement
    SET SettlementStatusId = @NewStatusId,
        ApprovedBy = CASE WHEN @NewStatusId = 2 THEN @ChangedBy ELSE ApprovedBy END,
        ApprovedDateUtc = CASE WHEN @NewStatusId = 2 THEN SYSUTCDATETIME() ELSE ApprovedDateUtc END,
        FailureReason = CASE WHEN @NewStatusId IN (5, 6) THEN @Remarks ELSE FailureReason END,
        ModifiedBy = @ChangedBy,
        ModifiedDateUtc = SYSUTCDATETIME()
    WHERE SettlementId = @SettlementId AND SettlementStatusId = @ExpectedStatusId;

    IF @@ROWCOUNT = 0
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM fin.Settlement WHERE SettlementId = @SettlementId)
            THROW 50404, N'SETTLEMENT_NOT_FOUND|Settlement was not found.', 1;
        THROW 50409, N'SETTLEMENT_STATUS_CHANGED|The settlement status was changed by another request. Reload and try again.', 1;
    END
END
GO

-- Processing -> Completed; closes the trip and, if the booking is paid, the booking too.
CREATE OR ALTER PROCEDURE fin.usp_Settlement_Complete
    @SettlementId          BIGINT,
    @TransactionReference  VARCHAR(100),
    @ChangedBy             BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @TripId BIGINT, @BookingId BIGINT;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE fin.Settlement
        SET @TripId = TripId, SettlementStatusId = 4, SettlementDateUtc = @Now, TransactionReference = @TransactionReference,
            ModifiedBy = @ChangedBy, ModifiedDateUtc = @Now
        WHERE SettlementId = @SettlementId AND SettlementStatusId = 3;

        IF @@ROWCOUNT = 0
            THROW 50400, N'SETTLEMENT_NOT_PROCESSING|Only settlements in processing can be completed.', 1;

        UPDATE core.Trip SET @BookingId = BookingId, TripStatusId = 7, ModifiedBy = @ChangedBy, ModifiedDateUtc = @Now
        WHERE TripId = @TripId AND TripStatusId = 6;

        IF @@ROWCOUNT > 0
            INSERT INTO core.TripStatusHistory (TripId, FromStatusId, ToStatusId, Remarks, ChangedBy, ChangedDateUtc)
            VALUES (@TripId, 6, 7, N'Owner settled', @ChangedBy, @Now);

        IF @BookingId IS NOT NULL
        BEGIN
            UPDATE core.Booking SET BookingStatusId = 11, ModifiedBy = @ChangedBy, ModifiedDateUtc = @Now
            WHERE BookingId = @BookingId AND BookingStatusId = 10;

            IF @@ROWCOUNT > 0
                INSERT INTO core.BookingStatusHistory (BookingId, FromStatusId, ToStatusId, Remarks, ChangedBy, ChangedDateUtc)
                VALUES (@BookingId, 10, 11, N'Trip settled and closed', @ChangedBy, @Now);
        END

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Settlement_GetById
    @SettlementId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        s.SettlementId,
        s.SettlementNumber,
        s.TripId,
        t.TripNumber,
        b.BookingNumber,
        s.OwnerId,
        o.FullName AS OwnerName,
        s.OwnerBankAccountId,
        ba.BankName,
        ba.AccountNumberLast4,
        s.GrossAmount,
        s.CommissionPercent,
        s.CommissionAmount,
        s.TaxAmount,
        s.AdjustmentAmount,
        s.NetAmount,
        s.SettlementStatusId,
        s.CreatedBy,
        o.UserId AS OwnerUserId,
        s.ApprovedDateUtc,
        s.SettlementDateUtc,
        s.TransactionReference,
        s.FailureReason,
        s.CreatedDateUtc,
        s.RowVersion
    FROM fin.Settlement AS s
    INNER JOIN core.Trip         AS t  ON t.TripId = s.TripId
    INNER JOIN core.Booking      AS b  ON b.BookingId = t.BookingId
    INNER JOIN core.VehicleOwner AS o  ON o.OwnerId = s.OwnerId
    LEFT  JOIN core.OwnerBankAccount AS ba ON ba.OwnerBankAccountId = s.OwnerBankAccountId
    WHERE s.SettlementId = @SettlementId;
END
GO

CREATE OR ALTER PROCEDURE fin.usp_SettlementItem_GetBySettlement
    @SettlementId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT si.SettlementItemId, si.ItemType, si.Description, si.Amount, si.SortOrder
    FROM fin.SettlementItem AS si
    WHERE si.SettlementId = @SettlementId
    ORDER BY si.SortOrder, si.SettlementItemId;
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Settlement_GetPaged
    @PageNumber          INT,
    @PageSize            INT,
    @Search              NVARCHAR(100) = NULL,
    @OwnerId             BIGINT        = NULL,
    @SettlementStatusId  INT           = NULL,
    @FromDateUtc         DATETIME2(3)  = NULL,
    @ToDateUtc           DATETIME2(3)  = NULL,
    @SortBy              VARCHAR(50)   = 'CreatedDate',
    @SortDirection       VARCHAR(4)    = 'DESC'
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        s.SettlementId,
        s.SettlementNumber,
        s.TripId,
        t.TripNumber,
        s.OwnerId,
        o.FullName AS OwnerName,
        s.GrossAmount,
        s.CommissionAmount,
        s.NetAmount,
        s.SettlementStatusId,
        s.SettlementDateUtc,
        s.CreatedDateUtc,
        COUNT(*) OVER () AS TotalRecords
    FROM fin.Settlement AS s
    INNER JOIN core.Trip         AS t ON t.TripId = s.TripId
    INNER JOIN core.VehicleOwner AS o ON o.OwnerId = s.OwnerId
    WHERE (@OwnerId IS NULL OR s.OwnerId = @OwnerId)
      AND (@SettlementStatusId IS NULL OR s.SettlementStatusId = @SettlementStatusId)
      AND (@FromDateUtc IS NULL OR s.CreatedDateUtc >= @FromDateUtc)
      AND (@ToDateUtc IS NULL OR s.CreatedDateUtc < @ToDateUtc)
      AND (@Search IS NULL OR s.SettlementNumber LIKE @Search + '%' OR t.TripNumber LIKE @Search + '%' OR o.FullName LIKE N'%' + @Search + N'%')
    ORDER BY
        CASE WHEN @SortBy = 'Net'         AND @SortDirection = 'ASC'  THEN s.NetAmount END ASC,
        CASE WHEN @SortBy = 'Net'         AND @SortDirection = 'DESC' THEN s.NetAmount END DESC,
        CASE WHEN @SortBy = 'CreatedDate' AND @SortDirection = 'ASC'  THEN s.CreatedDateUtc END ASC,
        s.CreatedDateUtc DESC,
        s.SettlementId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY
    OPTION (RECOMPILE);
END
GO

CREATE OR ALTER PROCEDURE fin.usp_Settlement_GetOwnerSummary
    @OwnerId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        CAST(ISNULL(SUM(CASE WHEN s.SettlementStatusId = 4 THEN s.NetAmount END), 0) AS DECIMAL(14,2)) AS TotalEarned,
        CAST(ISNULL(SUM(CASE WHEN s.SettlementStatusId IN (1, 2, 3) THEN s.NetAmount END), 0) AS DECIMAL(14,2)) AS PendingAmount,
        ISNULL(SUM(CASE WHEN s.SettlementStatusId = 4 THEN 1 ELSE 0 END), 0) AS CompletedCount,
        ISNULL(SUM(CASE WHEN s.SettlementStatusId IN (1, 2, 3) THEN 1 ELSE 0 END), 0) AS PendingCount,
        MAX(s.SettlementDateUtc) AS LastSettlementDateUtc
    FROM fin.Settlement AS s
    WHERE s.OwnerId = @OwnerId;
END
GO

-- Completed trips with a fully paid invoice and no live settlement: the Finance "ready to settle" queue.
CREATE OR ALTER PROCEDURE fin.usp_Settlement_GetEligibleTrips
    @PageNumber INT,
    @PageSize   INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        t.TripId,
        t.TripNumber,
        b.BookingNumber,
        t.OwnerId,
        o.FullName AS OwnerName,
        v.VehicleTypeId,
        i.SubTotal AS InvoiceSubTotal,
        t.ActualDeliveryDateUtc,
        COUNT(*) OVER () AS TotalRecords
    FROM core.Trip AS t
    INNER JOIN core.Booking      AS b ON b.BookingId = t.BookingId
    INNER JOIN core.VehicleOwner AS o ON o.OwnerId = t.OwnerId
    INNER JOIN core.Vehicle      AS v ON v.VehicleId = t.VehicleId
    INNER JOIN fin.Invoice       AS i ON i.TripId = t.TripId AND i.InvoiceStatusId = 4
    WHERE t.TripStatusId = 6
      AND NOT EXISTS (SELECT 1 FROM fin.Settlement AS s WHERE s.TripId = t.TripId AND s.SettlementStatusId NOT IN (5, 6))
    ORDER BY t.ActualDeliveryDateUtc, t.TripId
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

GO

-- >>>>> 08-StoredProcedures/14_Support_Notifications_Audit.sql
/*
    Module: Complaints, support tickets, contact enquiries, notifications and audit (schemas sup, aud)
    Complaint status: 1 Open, 2 Assigned, 3 Investigating, 4 Resolved, 5 Rejected, 6 Closed
    Ticket status   : 1 Open, 2 InProgress, 3 WaitingOnCustomer, 4 Resolved, 5 Closed
*/

CREATE OR ALTER PROCEDURE sup.usp_Complaint_Create
    @RaisedByUserId  BIGINT,
    @BookingId       BIGINT,
    @TripId          BIGINT,
    @Category        VARCHAR(30),
    @Subject         NVARCHAR(200),
    @Description     NVARCHAR(2000)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @Number VARCHAR(30) = core.fn_FormatBusinessNumber('CMP', NEXT VALUE FOR sup.seq_ComplaintNumber, @Now);

    INSERT INTO sup.Complaint (ComplaintNumber, RaisedByUserId, BookingId, TripId, Category, Subject, Description, ComplaintStatusId, CreatedBy, CreatedDateUtc)
    VALUES (@Number, @RaisedByUserId, @BookingId, @TripId, @Category, @Subject, @Description, 1, @RaisedByUserId, @Now);

    SELECT CAST(SCOPE_IDENTITY() AS BIGINT) AS Id, @Number AS Number;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_Complaint_GetById
    @ComplaintId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT c.ComplaintId, c.ComplaintNumber, c.RaisedByUserId, ru.FullName AS RaisedByName, c.BookingId, b.BookingNumber,
           c.TripId, t.TripNumber, c.Category, c.Subject, c.Description, c.ComplaintStatusId, c.AssignedToUserId,
           au.FullName AS AssignedToName, c.Resolution, c.ResolvedDateUtc, c.CreatedDateUtc, c.RowVersion
    FROM sup.Complaint AS c
    INNER JOIN sec.[User]   AS ru ON ru.UserId = c.RaisedByUserId
    LEFT  JOIN sec.[User]   AS au ON au.UserId = c.AssignedToUserId
    LEFT  JOIN core.Booking AS b  ON b.BookingId = c.BookingId
    LEFT  JOIN core.Trip    AS t  ON t.TripId = c.TripId
    WHERE c.ComplaintId = @ComplaintId;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_Complaint_GetPaged
    @PageNumber         INT,
    @PageSize           INT,
    @Search             NVARCHAR(100) = NULL,
    @RaisedByUserId     BIGINT        = NULL,
    @AssignedToUserId   BIGINT        = NULL,
    @ComplaintStatusId  INT           = NULL,
    @Category           VARCHAR(30)   = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT c.ComplaintId, c.ComplaintNumber, ru.FullName AS RaisedByName, c.Category, c.Subject, c.ComplaintStatusId,
           au.FullName AS AssignedToName, c.CreatedDateUtc, COUNT(*) OVER () AS TotalRecords
    FROM sup.Complaint AS c
    INNER JOIN sec.[User] AS ru ON ru.UserId = c.RaisedByUserId
    LEFT  JOIN sec.[User] AS au ON au.UserId = c.AssignedToUserId
    WHERE (@RaisedByUserId IS NULL OR c.RaisedByUserId = @RaisedByUserId)
      AND (@AssignedToUserId IS NULL OR c.AssignedToUserId = @AssignedToUserId)
      AND (@ComplaintStatusId IS NULL OR c.ComplaintStatusId = @ComplaintStatusId)
      AND (@Category IS NULL OR c.Category = @Category)
      AND (@Search IS NULL OR c.ComplaintNumber LIKE @Search + '%' OR c.Subject LIKE N'%' + @Search + N'%')
    ORDER BY c.CreatedDateUtc DESC, c.ComplaintId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY
    OPTION (RECOMPILE);
END
GO

CREATE OR ALTER PROCEDURE sup.usp_Complaint_Assign
    @ComplaintId       BIGINT,
    @AssignedToUserId  BIGINT,
    @ModifiedBy        BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT EXISTS (SELECT 1 FROM sec.[User] WHERE UserId = @AssignedToUserId AND IsInternal = 1 AND IsActive = 1 AND IsDeleted = 0)
        THROW 50400, N'ASSIGNEE_INVALID|Complaints can only be assigned to active internal users.', 1;

    UPDATE sup.Complaint
    SET AssignedToUserId = @AssignedToUserId,
        ComplaintStatusId = CASE WHEN ComplaintStatusId = 1 THEN 2 ELSE ComplaintStatusId END,
        ModifiedBy = @ModifiedBy, ModifiedDateUtc = SYSUTCDATETIME()
    WHERE ComplaintId = @ComplaintId AND ComplaintStatusId IN (1, 2, 3);

    IF @@ROWCOUNT = 0
        THROW 50400, N'COMPLAINT_NOT_ASSIGNABLE|Only open complaints can be assigned.', 1;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_Complaint_ChangeStatus
    @ComplaintId       BIGINT,
    @ExpectedStatusId  INT,
    @NewStatusId       INT,
    @Resolution        NVARCHAR(2000),
    @ModifiedBy        BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE sup.Complaint
    SET ComplaintStatusId = @NewStatusId,
        Resolution = CASE WHEN @Resolution IS NOT NULL THEN @Resolution ELSE Resolution END,
        ResolvedDateUtc = CASE WHEN @NewStatusId IN (4, 5) THEN SYSUTCDATETIME() ELSE ResolvedDateUtc END,
        ModifiedBy = @ModifiedBy, ModifiedDateUtc = SYSUTCDATETIME()
    WHERE ComplaintId = @ComplaintId AND ComplaintStatusId = @ExpectedStatusId;

    IF @@ROWCOUNT = 0
    BEGIN
        IF NOT EXISTS (SELECT 1 FROM sup.Complaint WHERE ComplaintId = @ComplaintId)
            THROW 50404, N'COMPLAINT_NOT_FOUND|Complaint was not found.', 1;
        THROW 50409, N'COMPLAINT_STATUS_CHANGED|The complaint status was changed by another request.', 1;
    END
END
GO

CREATE OR ALTER PROCEDURE sup.usp_SupportTicket_Create
    @RaisedByUserId    BIGINT,
    @BookingId         BIGINT,
    @Subject           NVARCHAR(200),
    @Description       NVARCHAR(2000),
    @TicketPriorityId  INT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Now DATETIME2(3) = SYSUTCDATETIME();
    DECLARE @Number VARCHAR(30) = core.fn_FormatBusinessNumber('TKT', NEXT VALUE FOR sup.seq_TicketNumber, @Now);

    INSERT INTO sup.SupportTicket (TicketNumber, RaisedByUserId, BookingId, Subject, Description, TicketPriorityId, TicketStatusId, CreatedBy, CreatedDateUtc)
    VALUES (@Number, @RaisedByUserId, @BookingId, @Subject, @Description, @TicketPriorityId, 1, @RaisedByUserId, @Now);

    SELECT CAST(SCOPE_IDENTITY() AS BIGINT) AS Id, @Number AS Number;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_SupportTicket_GetById
    @SupportTicketId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT st.SupportTicketId, st.TicketNumber, st.RaisedByUserId, ru.FullName AS RaisedByName, st.BookingId, b.BookingNumber,
           st.Subject, st.Description, st.TicketPriorityId, st.TicketStatusId, st.AssignedToUserId, au.FullName AS AssignedToName,
           st.ClosedDateUtc, st.CreatedDateUtc, st.RowVersion
    FROM sup.SupportTicket AS st
    INNER JOIN sec.[User]   AS ru ON ru.UserId = st.RaisedByUserId
    LEFT  JOIN sec.[User]   AS au ON au.UserId = st.AssignedToUserId
    LEFT  JOIN core.Booking AS b  ON b.BookingId = st.BookingId
    WHERE st.SupportTicketId = @SupportTicketId;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_SupportTicket_GetPaged
    @PageNumber        INT,
    @PageSize          INT,
    @Search            NVARCHAR(100) = NULL,
    @RaisedByUserId    BIGINT        = NULL,
    @AssignedToUserId  BIGINT        = NULL,
    @TicketStatusId    INT           = NULL,
    @TicketPriorityId  INT           = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT st.SupportTicketId, st.TicketNumber, ru.FullName AS RaisedByName, st.Subject, st.TicketPriorityId, st.TicketStatusId,
           au.FullName AS AssignedToName, st.CreatedDateUtc, COUNT(*) OVER () AS TotalRecords
    FROM sup.SupportTicket AS st
    INNER JOIN sec.[User] AS ru ON ru.UserId = st.RaisedByUserId
    LEFT  JOIN sec.[User] AS au ON au.UserId = st.AssignedToUserId
    WHERE (@RaisedByUserId IS NULL OR st.RaisedByUserId = @RaisedByUserId)
      AND (@AssignedToUserId IS NULL OR st.AssignedToUserId = @AssignedToUserId)
      AND (@TicketStatusId IS NULL OR st.TicketStatusId = @TicketStatusId)
      AND (@TicketPriorityId IS NULL OR st.TicketPriorityId = @TicketPriorityId)
      AND (@Search IS NULL OR st.TicketNumber LIKE @Search + '%' OR st.Subject LIKE N'%' + @Search + N'%')
    ORDER BY st.TicketPriorityId DESC, st.CreatedDateUtc DESC, st.SupportTicketId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY
    OPTION (RECOMPILE);
END
GO

CREATE OR ALTER PROCEDURE sup.usp_SupportTicket_Update
    @SupportTicketId   BIGINT,
    @AssignedToUserId  BIGINT,
    @TicketStatusId    INT,
    @TicketPriorityId  INT,
    @ModifiedBy        BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    IF @AssignedToUserId IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM sec.[User] WHERE UserId = @AssignedToUserId AND IsInternal = 1 AND IsActive = 1 AND IsDeleted = 0)
        THROW 50400, N'ASSIGNEE_INVALID|Tickets can only be assigned to active internal users.', 1;

    UPDATE sup.SupportTicket
    SET AssignedToUserId = ISNULL(@AssignedToUserId, AssignedToUserId),
        TicketStatusId = ISNULL(@TicketStatusId, TicketStatusId),
        TicketPriorityId = ISNULL(@TicketPriorityId, TicketPriorityId),
        ClosedDateUtc = CASE WHEN @TicketStatusId = 5 THEN SYSUTCDATETIME() WHEN @TicketStatusId IS NOT NULL THEN NULL ELSE ClosedDateUtc END,
        ModifiedBy = @ModifiedBy, ModifiedDateUtc = SYSUTCDATETIME()
    WHERE SupportTicketId = @SupportTicketId;

    IF @@ROWCOUNT = 0
        THROW 50404, N'TICKET_NOT_FOUND|Support ticket was not found.', 1;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_SupportTicketComment_Create
    @SupportTicketId  BIGINT,
    @CommentText      NVARCHAR(2000),
    @IsInternal       BIT,
    @CreatedBy        BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Id BIGINT;

    BEGIN TRANSACTION;
        INSERT INTO sup.SupportTicketComment (SupportTicketId, CommentText, IsInternal, CreatedBy)
        VALUES (@SupportTicketId, @CommentText, @IsInternal, @CreatedBy);
        SET @Id = SCOPE_IDENTITY();

        -- a reply from the requester re-opens a ticket that was waiting on them
        UPDATE sup.SupportTicket SET TicketStatusId = 2, ModifiedBy = @CreatedBy, ModifiedDateUtc = SYSUTCDATETIME()
        WHERE SupportTicketId = @SupportTicketId AND RaisedByUserId = @CreatedBy AND TicketStatusId IN (3, 4);
    COMMIT TRANSACTION;

    SELECT @Id AS Id;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_SupportTicketComment_GetByTicket
    @SupportTicketId  BIGINT,
    @IncludeInternal  BIT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT c.SupportTicketCommentId, c.CommentText, c.IsInternal, c.CreatedBy, u.FullName AS CreatedByName, u.IsInternal AS IsStaff, c.CreatedDateUtc
    FROM sup.SupportTicketComment AS c
    INNER JOIN sec.[User] AS u ON u.UserId = c.CreatedBy
    WHERE c.SupportTicketId = @SupportTicketId AND (@IncludeInternal = 1 OR c.IsInternal = 0)
    ORDER BY c.CreatedDateUtc, c.SupportTicketCommentId;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_ContactEnquiry_Create
    @FullName     NVARCHAR(150),
    @Email        NVARCHAR(256),
    @PhoneNumber  VARCHAR(20),
    @Subject      NVARCHAR(200),
    @Message      NVARCHAR(2000),
    @IpAddress    VARCHAR(45)
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO sup.ContactEnquiry (FullName, Email, PhoneNumber, Subject, Message, IpAddress)
    VALUES (@FullName, @Email, @PhoneNumber, @Subject, @Message, @IpAddress);
    SELECT CAST(SCOPE_IDENTITY() AS BIGINT) AS Id;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_ContactEnquiry_GetPaged
    @PageNumber  INT,
    @PageSize    INT,
    @IsHandled   BIT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT ce.ContactEnquiryId, ce.FullName, ce.Email, ce.PhoneNumber, ce.Subject, ce.Message, ce.IsHandled, ce.HandledDateUtc,
           ce.CreatedDateUtc, COUNT(*) OVER () AS TotalRecords
    FROM sup.ContactEnquiry AS ce
    WHERE @IsHandled IS NULL OR ce.IsHandled = @IsHandled
    ORDER BY ce.CreatedDateUtc DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_ContactEnquiry_MarkHandled
    @ContactEnquiryId  BIGINT,
    @HandledBy         BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE sup.ContactEnquiry SET IsHandled = 1, HandledBy = @HandledBy, HandledDateUtc = SYSUTCDATETIME()
    WHERE ContactEnquiryId = @ContactEnquiryId;
    IF @@ROWCOUNT = 0
        THROW 50404, N'ENQUIRY_NOT_FOUND|Enquiry was not found.', 1;
END
GO

-- ===== Notifications =====

CREATE OR ALTER PROCEDURE sup.usp_NotificationTemplate_GetByCode
    @TemplateCode VARCHAR(60)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT nt.NotificationTemplateId, nt.TemplateCode, nt.NotificationChannelId, nt.Subject, nt.Body, nt.IsActive
    FROM sup.NotificationTemplate AS nt
    WHERE nt.TemplateCode = @TemplateCode AND nt.IsActive = 1;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_NotificationTemplate_GetAll
AS
BEGIN
    SET NOCOUNT ON;
    SELECT nt.NotificationTemplateId, nt.TemplateCode, nt.NotificationChannelId, nt.Subject, nt.Body, nt.IsActive
    FROM sup.NotificationTemplate AS nt
    ORDER BY nt.TemplateCode, nt.NotificationChannelId;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_NotificationTemplate_Update
    @NotificationTemplateId  INT,
    @Subject                 NVARCHAR(200),
    @Body                    NVARCHAR(4000),
    @IsActive                BIT,
    @ModifiedBy              BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE sup.NotificationTemplate
    SET Subject = @Subject, Body = @Body, IsActive = @IsActive, ModifiedBy = @ModifiedBy, ModifiedDateUtc = SYSUTCDATETIME()
    WHERE NotificationTemplateId = @NotificationTemplateId;
    IF @@ROWCOUNT = 0
        THROW 50404, N'TEMPLATE_NOT_FOUND|Notification template was not found.', 1;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_Notification_Create
    @UserId                 BIGINT,
    @NotificationChannelId  INT,
    @TemplateCode           VARCHAR(60),
    @Title                  NVARCHAR(200),
    @Message                NVARCHAR(2000),
    @NotificationStatusId   INT,
    @EntityType             VARCHAR(30),
    @EntityId               BIGINT,
    @FailureReason          NVARCHAR(500)
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO sup.Notification (UserId, NotificationChannelId, TemplateCode, Title, Message, NotificationStatusId, EntityType, EntityId, FailureReason, SentDateUtc)
    VALUES (@UserId, @NotificationChannelId, @TemplateCode, @Title, @Message, @NotificationStatusId, @EntityType, @EntityId, @FailureReason,
            CASE WHEN @NotificationStatusId = 2 THEN SYSUTCDATETIME() ELSE NULL END);
    SELECT CAST(SCOPE_IDENTITY() AS BIGINT) AS Id;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_Notification_GetByUser
    @UserId      BIGINT,
    @PageNumber  INT,
    @PageSize    INT,
    @UnreadOnly  BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SELECT n.NotificationId, n.TemplateCode, n.Title, n.Message, n.EntityType, n.EntityId, n.ReadDateUtc, n.CreatedDateUtc,
           COUNT(*) OVER () AS TotalRecords
    FROM sup.Notification AS n
    WHERE n.UserId = @UserId AND n.NotificationChannelId = 1 AND (@UnreadOnly = 0 OR n.ReadDateUtc IS NULL)
    ORDER BY n.CreatedDateUtc DESC, n.NotificationId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_Notification_GetUnreadCount
    @UserId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT CAST(COUNT(*) AS BIGINT) AS Id
    FROM sup.Notification
    WHERE UserId = @UserId AND NotificationChannelId = 1 AND ReadDateUtc IS NULL;
END
GO

CREATE OR ALTER PROCEDURE sup.usp_Notification_MarkRead
    @UserId          BIGINT,
    @NotificationId  BIGINT = NULL     -- NULL => mark all as read
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE sup.Notification SET ReadDateUtc = SYSUTCDATETIME()
    WHERE UserId = @UserId AND ReadDateUtc IS NULL AND NotificationChannelId = 1
      AND (@NotificationId IS NULL OR NotificationId = @NotificationId);
END
GO

-- ===== Audit =====

CREATE OR ALTER PROCEDURE aud.usp_AuditLog_Create
    @UserId      BIGINT,
    @Action      VARCHAR(100),
    @EntityType  VARCHAR(50),
    @EntityId    VARCHAR(50),
    @OldValue    NVARCHAR(4000),
    @NewValue    NVARCHAR(4000),
    @IpAddress   VARCHAR(45),
    @UserAgent   NVARCHAR(300),
    @TraceId     VARCHAR(64)
AS
BEGIN
    SET NOCOUNT ON;
    INSERT INTO aud.AuditLog (UserId, Action, EntityType, EntityId, OldValue, NewValue, IpAddress, UserAgent, TraceId)
    VALUES (@UserId, @Action, @EntityType, @EntityId, @OldValue, @NewValue, @IpAddress, LEFT(@UserAgent, 300), @TraceId);
END
GO

CREATE OR ALTER PROCEDURE aud.usp_AuditLog_GetPaged
    @PageNumber   INT,
    @PageSize     INT,
    @UserId       BIGINT        = NULL,
    @EntityType   VARCHAR(50)   = NULL,
    @EntityId     VARCHAR(50)   = NULL,
    @Action       VARCHAR(100)  = NULL,
    @FromDateUtc  DATETIME2(3)  = NULL,
    @ToDateUtc    DATETIME2(3)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SELECT a.AuditLogId, a.UserId, u.FullName AS UserName, a.Action, a.EntityType, a.EntityId, a.OldValue, a.NewValue,
           a.IpAddress, a.TraceId, a.CreatedDateUtc, COUNT(*) OVER () AS TotalRecords
    FROM aud.AuditLog AS a
    LEFT JOIN sec.[User] AS u ON u.UserId = a.UserId
    WHERE (@UserId IS NULL OR a.UserId = @UserId)
      AND (@EntityType IS NULL OR a.EntityType = @EntityType)
      AND (@EntityId IS NULL OR a.EntityId = @EntityId)
      AND (@Action IS NULL OR a.Action LIKE @Action + '%')
      AND (@FromDateUtc IS NULL OR a.CreatedDateUtc >= @FromDateUtc)
      AND (@ToDateUtc IS NULL OR a.CreatedDateUtc < @ToDateUtc)
    ORDER BY a.CreatedDateUtc DESC, a.AuditLogId DESC
    OFFSET (@PageNumber - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY
    OPTION (RECOMPILE);
END
GO

GO

-- >>>>> 08-StoredProcedures/15_Reports_Dashboard.sql
/*
    Module: Dashboards and reports (schema rpt)
    All date parameters are UTC; the API converts the user's local date range (IST) to UTC before calling.
*/

CREATE OR ALTER PROCEDURE rpt.usp_Dashboard_GetOperationsKpis
    @TodayStartUtc  DATETIME2(3),
    @MonthStartUtc  DATETIME2(3)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        (SELECT COUNT(*) FROM core.Booking)                                                         AS TotalBookings,
        (SELECT COUNT(*) FROM core.Booking WHERE CreatedDateUtc >= @TodayStartUtc)                  AS TodaysBookings,
        (SELECT COUNT(*) FROM core.Booking WHERE BookingStatusId IN (2, 3))                         AS PendingBookings,
        (SELECT COUNT(*) FROM core.Quotation WHERE QuotationStatusId = 2)                           AS PendingQuotations,
        (SELECT COUNT(*) FROM core.Booking WHERE BookingStatusId = 5)                               AS AwaitingAssignment,
        (SELECT COUNT(*) FROM core.Trip WHERE TripStatusId IN (1, 2, 3, 9, 10))                     AS ActiveTrips,
        (SELECT COUNT(*) FROM core.Trip WHERE TripStatusId = 10)                                    AS TripExceptions,
        (SELECT COUNT(*) FROM core.Trip WHERE TripStatusId IN (6, 7))                               AS CompletedTrips,
        (SELECT COUNT(*) FROM core.Trip WHERE TripStatusId = 8)                                     AS CancelledTrips,
        (SELECT COUNT(*) FROM core.VehicleOwner WHERE VerificationStatusId IN (1, 2) AND IsDeleted = 0) AS PendingOwnerApprovals,
        (SELECT COUNT(*) FROM core.Driver WHERE VerificationStatusId IN (1, 2) AND IsDeleted = 0)   AS PendingDriverApprovals,
        (SELECT COUNT(*) FROM core.Vehicle WHERE VerificationStatusId IN (1, 2) AND IsDeleted = 0)  AS PendingVehicleApprovals,
        (SELECT COUNT(*) FROM fin.Invoice WHERE InvoiceStatusId IN (2, 3))                          AS UnpaidInvoices,
        CAST((SELECT ISNULL(SUM(TotalAmount - PaidAmount), 0) FROM fin.Invoice WHERE InvoiceStatusId IN (2, 3)) AS DECIMAL(14,2)) AS OutstandingAmount,
        (SELECT COUNT(*) FROM fin.Settlement WHERE SettlementStatusId IN (1, 2, 3))                 AS PendingSettlements,
        CAST((SELECT ISNULL(SUM(NetAmount), 0) FROM fin.Settlement WHERE SettlementStatusId IN (1, 2, 3)) AS DECIMAL(14,2)) AS PendingSettlementAmount,
        CAST((SELECT ISNULL(SUM(TotalAmount), 0) FROM fin.Invoice WHERE InvoiceStatusId <> 5 AND InvoiceDateUtc >= @MonthStartUtc) AS DECIMAL(14,2)) AS RevenueThisMonth,
        CAST((SELECT ISNULL(SUM(Amount), 0) FROM fin.Payment WHERE PaymentStatusId IN (4, 6, 7) AND PaymentDateUtc >= @MonthStartUtc) AS DECIMAL(14,2)) AS CollectionsThisMonth,
        (SELECT COUNT(*) FROM sup.SupportTicket WHERE TicketStatusId IN (1, 2, 3))                  AS OpenTickets,
        (SELECT COUNT(*) FROM sup.Complaint WHERE ComplaintStatusId IN (1, 2, 3))                   AS OpenComplaints,
        (SELECT COUNT(*) FROM rpt.vw_VehicleCompliance WHERE DaysToNextExpiry <= 30)                AS VehiclesWithExpiringDocuments;
END
GO

CREATE OR ALTER PROCEDURE rpt.usp_Dashboard_GetCustomerSummary
    @CustomerId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        (SELECT COUNT(*) FROM core.Booking WHERE CustomerId = @CustomerId AND BookingStatusId IN (1, 2, 3, 4, 5, 6, 7, 13)) AS ActiveBookings,
        (SELECT COUNT(*) FROM core.Booking WHERE CustomerId = @CustomerId AND BookingStatusId = 4)  AS AwaitingQuotationResponse,
        (SELECT COUNT(*) FROM core.Booking WHERE CustomerId = @CustomerId AND BookingStatusId = 7)  AS InTransit,
        (SELECT COUNT(*) FROM core.Booking WHERE CustomerId = @CustomerId AND BookingStatusId IN (8, 9, 10, 11)) AS CompletedBookings,
        CAST((SELECT ISNULL(SUM(TotalAmount - PaidAmount), 0) FROM fin.Invoice WHERE CustomerId = @CustomerId AND InvoiceStatusId IN (2, 3)) AS DECIMAL(14,2)) AS OutstandingAmount,
        CAST((SELECT ISNULL(SUM(PaidAmount), 0) FROM fin.Invoice WHERE CustomerId = @CustomerId AND InvoiceStatusId <> 5) AS DECIMAL(14,2)) AS TotalPaid;
END
GO

CREATE OR ALTER PROCEDURE rpt.usp_Dashboard_GetOwnerSummary
    @OwnerId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        (SELECT COUNT(*) FROM core.Vehicle WHERE OwnerId = @OwnerId AND IsDeleted = 0)                              AS TotalVehicles,
        (SELECT COUNT(*) FROM core.Vehicle WHERE OwnerId = @OwnerId AND IsDeleted = 0 AND IsAvailable = 1)          AS AvailableVehicles,
        (SELECT COUNT(*) FROM core.Vehicle WHERE OwnerId = @OwnerId AND IsDeleted = 0 AND VerificationStatusId IN (1, 2)) AS VehiclesPendingVerification,
        (SELECT COUNT(*) FROM core.Driver WHERE OwnerId = @OwnerId AND IsDeleted = 0)                               AS TotalDrivers,
        (SELECT COUNT(*) FROM core.Trip WHERE OwnerId = @OwnerId AND TripStatusId IN (1, 2, 3, 9, 10))              AS ActiveTrips,
        (SELECT COUNT(*) FROM core.Trip WHERE OwnerId = @OwnerId AND TripStatusId IN (4, 5, 6, 7))                  AS CompletedTrips,
        CAST((SELECT ISNULL(SUM(NetAmount), 0) FROM fin.Settlement WHERE OwnerId = @OwnerId AND SettlementStatusId IN (1, 2, 3)) AS DECIMAL(14,2)) AS PendingSettlementAmount,
        CAST((SELECT ISNULL(SUM(NetAmount), 0) FROM fin.Settlement WHERE OwnerId = @OwnerId AND SettlementStatusId = 4) AS DECIMAL(14,2)) AS TotalEarned;
END
GO

CREATE OR ALTER PROCEDURE rpt.usp_Dashboard_GetDriverSummary
    @DriverId BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        (SELECT COUNT(*) FROM core.Trip WHERE DriverId = @DriverId AND TripStatusId IN (2, 3, 9, 10)) AS ActiveTrips,
        (SELECT COUNT(*) FROM core.Trip WHERE DriverId = @DriverId AND TripStatusId = 1)               AS UpcomingTrips,
        (SELECT COUNT(*) FROM core.Trip WHERE DriverId = @DriverId AND TripStatusId IN (4, 5, 6, 7))   AS CompletedTrips,
        d.AvailabilityStatusId
    FROM core.Driver AS d
    WHERE d.DriverId = @DriverId;
END
GO

CREATE OR ALTER PROCEDURE rpt.usp_Report_BookingsByDay
    @FromUtc DATETIME2(3),
    @ToUtc   DATETIME2(3)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        CAST(b.CreatedDateUtc AS DATE) AS ReportDate,
        COUNT(*) AS TotalBookings,
        SUM(CASE WHEN b.BookingStatusId IN (5, 6, 7, 8, 9, 10, 11) THEN 1 ELSE 0 END) AS ConfirmedBookings,
        SUM(CASE WHEN b.BookingStatusId IN (12, 14) THEN 1 ELSE 0 END) AS CancelledOrRejected
    FROM core.Booking AS b
    WHERE b.CreatedDateUtc >= @FromUtc AND b.CreatedDateUtc < @ToUtc
    GROUP BY CAST(b.CreatedDateUtc AS DATE)
    ORDER BY ReportDate;
END
GO

CREATE OR ALTER PROCEDURE rpt.usp_Report_BookingsByStatus
    @FromUtc DATETIME2(3),
    @ToUtc   DATETIME2(3)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT bs.BookingStatusId AS StatusId, bs.Name AS StatusName, COUNT(b.BookingId) AS ItemCount
    FROM mst.BookingStatus AS bs
    LEFT JOIN core.Booking AS b ON b.BookingStatusId = bs.BookingStatusId AND b.CreatedDateUtc >= @FromUtc AND b.CreatedDateUtc < @ToUtc
    GROUP BY bs.BookingStatusId, bs.Name, bs.SortOrder
    ORDER BY bs.SortOrder;
END
GO

CREATE OR ALTER PROCEDURE rpt.usp_Report_Revenue
    @FromUtc  DATETIME2(3),
    @ToUtc    DATETIME2(3),
    @GroupBy  VARCHAR(10)      -- Day | Month
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        CASE WHEN @GroupBy = 'Month' THEN DATEFROMPARTS(YEAR(dr.RevenueDate), MONTH(dr.RevenueDate), 1) ELSE dr.RevenueDate END AS Period,
        CAST(SUM(dr.InvoiceCount) AS INT)    AS InvoiceCount,
        CAST(SUM(dr.SubTotal) AS DECIMAL(14,2))    AS SubTotal,
        CAST(SUM(dr.TaxAmount) AS DECIMAL(14,2))   AS TaxAmount,
        CAST(SUM(dr.TotalAmount) AS DECIMAL(14,2)) AS TotalAmount,
        CAST(SUM(dr.PaidAmount) AS DECIMAL(14,2))  AS PaidAmount
    FROM rpt.vw_DailyRevenue AS dr
    WHERE dr.RevenueDate >= CAST(@FromUtc AS DATE) AND dr.RevenueDate < CAST(@ToUtc AS DATE)
    GROUP BY CASE WHEN @GroupBy = 'Month' THEN DATEFROMPARTS(YEAR(dr.RevenueDate), MONTH(dr.RevenueDate), 1) ELSE dr.RevenueDate END
    ORDER BY Period;
END
GO

CREATE OR ALTER PROCEDURE rpt.usp_Report_TripPerformance
    @FromUtc DATETIME2(3),
    @ToUtc   DATETIME2(3)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        vt.VehicleTypeId,
        vt.Name AS VehicleTypeName,
        COUNT(*) AS TripCount,
        SUM(CASE WHEN t.ActualDeliveryDateUtc IS NOT NULL THEN 1 ELSE 0 END) AS DeliveredCount,
        SUM(CASE WHEN t.ActualDeliveryDateUtc IS NOT NULL AND t.ActualDeliveryDateUtc <= t.PlannedDeliveryDateUtc THEN 1 ELSE 0 END) AS OnTimeCount,
        SUM(CASE WHEN t.TripStatusId = 8 THEN 1 ELSE 0 END) AS CancelledCount,
        CAST(AVG(CASE WHEN t.ActualDeliveryDateUtc IS NOT NULL AND t.ActualPickupDateUtc IS NOT NULL
                      THEN DATEDIFF(MINUTE, t.ActualPickupDateUtc, t.ActualDeliveryDateUtc) / 60.0 END) AS DECIMAL(10,2)) AS AverageTransitHours
    FROM core.Trip AS t
    INNER JOIN core.Vehicle    AS v  ON v.VehicleId = t.VehicleId
    INNER JOIN mst.VehicleType AS vt ON vt.VehicleTypeId = v.VehicleTypeId
    WHERE t.PlannedPickupDateUtc >= @FromUtc AND t.PlannedPickupDateUtc < @ToUtc
    GROUP BY vt.VehicleTypeId, vt.Name, vt.SortOrder
    ORDER BY vt.SortOrder;
END
GO

CREATE OR ALTER PROCEDURE rpt.usp_Report_Settlements
    @FromUtc DATETIME2(3),
    @ToUtc   DATETIME2(3)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT ss.SettlementStatusId AS StatusId, ss.Name AS StatusName, COUNT(s.SettlementId) AS SettlementCount,
           CAST(ISNULL(SUM(s.GrossAmount), 0) AS DECIMAL(14,2)) AS GrossAmount,
           CAST(ISNULL(SUM(s.CommissionAmount), 0) AS DECIMAL(14,2)) AS CommissionAmount,
           CAST(ISNULL(SUM(s.NetAmount), 0) AS DECIMAL(14,2)) AS NetAmount
    FROM mst.SettlementStatus AS ss
    LEFT JOIN fin.Settlement AS s ON s.SettlementStatusId = ss.SettlementStatusId AND s.CreatedDateUtc >= @FromUtc AND s.CreatedDateUtc < @ToUtc
    GROUP BY ss.SettlementStatusId, ss.Name, ss.SortOrder
    ORDER BY ss.SortOrder;
END
GO

CREATE OR ALTER PROCEDURE rpt.usp_Report_TopCustomers
    @FromUtc DATETIME2(3),
    @ToUtc   DATETIME2(3),
    @Top     INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP (@Top)
        c.CustomerId,
        c.CustomerNumber,
        c.FullName AS CustomerName,
        COUNT(DISTINCT b.BookingId) AS BookingCount,
        CAST(ISNULL(SUM(i.TotalAmount), 0) AS DECIMAL(14,2)) AS InvoicedAmount
    FROM core.Customer AS c
    INNER JOIN core.Booking AS b ON b.CustomerId = c.CustomerId AND b.CreatedDateUtc >= @FromUtc AND b.CreatedDateUtc < @ToUtc
    LEFT  JOIN fin.Invoice  AS i ON i.BookingId = b.BookingId AND i.InvoiceStatusId <> 5
    GROUP BY c.CustomerId, c.CustomerNumber, c.FullName
    ORDER BY InvoicedAmount DESC, BookingCount DESC;
END
GO

-- Partner population by verification/activity status, for the "customers / owners / drivers / vehicles" reports.
CREATE OR ALTER PROCEDURE rpt.usp_Report_PartnerSummary
AS
BEGIN
    SET NOCOUNT ON;
    SELECT 'Customers' AS EntityType, CASE WHEN c.IsActive = 1 THEN N'Active' ELSE N'Inactive' END AS StatusName, COUNT(*) AS ItemCount
    FROM core.Customer AS c WHERE c.IsDeleted = 0 GROUP BY c.IsActive
    UNION ALL
    SELECT 'Owners', vs.Name, COUNT(*) FROM core.VehicleOwner AS o
    INNER JOIN mst.VerificationStatus AS vs ON vs.VerificationStatusId = o.VerificationStatusId
    WHERE o.IsDeleted = 0 GROUP BY vs.Name
    UNION ALL
    SELECT 'Drivers', vs.Name, COUNT(*) FROM core.Driver AS d
    INNER JOIN mst.VerificationStatus AS vs ON vs.VerificationStatusId = d.VerificationStatusId
    WHERE d.IsDeleted = 0 GROUP BY vs.Name
    UNION ALL
    SELECT 'Vehicles', vs.Name, COUNT(*) FROM core.Vehicle AS v
    INNER JOIN mst.VerificationStatus AS vs ON vs.VerificationStatusId = v.VerificationStatusId
    WHERE v.IsDeleted = 0 GROUP BY vs.Name;
END
GO

